namespace Sim.Controllers {
    /// <summary>
    /// Publishes the authoritative vehicle pose and body-frame twist used by ROS navigation.
    /// This component is opt-in so existing scene-owned odometry publishers are not duplicated.
    /// </summary>
    public sealed class CraneROSNavigationState : MonoBehaviour, ICraneEpisodeResettable {
        private IPhysicsBody body;
        private Component bodyComponent;
        private ROSConnection ros;
        private string odometryTopic;
        private string transformTopic;
        private string odometryFrame;
        private string baseFrame;
        private double publishPeriod;
        private double nextPublishTime;
        private long publisherEpisodeId;
        private bool useRoboBoatFrame;
        private readonly List<Transform> childFrames = new();
        private string[] requestedChildFrameNames = Array.Empty<string>();

        public int ResetPriority => -80;

        public void Initialize(Component target, string odomTopic, string tfTopic,
            string parentFrame, string childFrame, float publishRateHz,
            IReadOnlyList<string> requestedChildFrames, bool correctRoboBoatBow = false) {
            bodyComponent = target != null ? target : throw new ArgumentNullException(nameof(target));
            body = target switch {
                Rigidbody rigidbody => new RigidbodyAdapter(rigidbody),
                ArticulationBody articulation => new ArticulationBodyAdapter(articulation),
                _ => throw new ArgumentException("Navigation state requires a PhysX body.",
                    nameof(target))
            };
            odometryTopic = odomTopic;
            transformTopic = tfTopic;
            odometryFrame = parentFrame;
            baseFrame = childFrame;
            publishPeriod = 1.0 / Math.Max(0.1f, publishRateHz);
            nextPublishTime = 0;
            publisherEpisodeId = CraneRuntimeMetrics.EpisodeId;
            useRoboBoatFrame = correctRoboBoatBow;
            requestedChildFrameNames = requestedChildFrames == null
                ? Array.Empty<string>()
                : new List<string>(requestedChildFrames).ToArray();
            CacheChildFrames(requestedChildFrames);

            ros = ROSConnection.GetOrCreateInstance();
            ros.RegisterPublisher<OdometryMsg>(odometryTopic);
            ros.RegisterPublisher<TFMessageMsg>(transformTopic);
            Debug.Log($"CRANE_ROS_NAV_STATE_READY body={bodyComponent.name} " +
                      $"bodyType={bodyComponent.GetType().Name} odom={odometryTopic} " +
                      $"tf={transformTopic} frames={odometryFrame}->{baseFrame} " +
                      $"rateHz={publishRateHz:R} childFrames={childFrames.Count}");
        }

        private void CacheChildFrames(IReadOnlyList<string> requestedFrames) {
            childFrames.Clear();
            if (requestedFrames == null || requestedFrames.Count == 0) return;
            Transform[] descendants = body.transform.GetComponentsInChildren<Transform>(true);
            foreach (string requested in requestedFrames) {
                Transform match = null;
                foreach (Transform candidate in descendants) {
                    if (candidate != body.transform && candidate.name == requested) {
                        match = candidate;
                        break;
                    }
                }
                if (match != null) childFrames.Add(match);
                else Debug.LogWarning($"CRANE_ROS_NAV_CHILD_FRAME_UNAVAILABLE " +
                                      $"body={bodyComponent.name} frame={requested}");
            }
        }

        public void CaptureEpisodeInitialState() { }

        public void ResetEpisode(in CraneEpisodeResetContext context,
            CraneEpisodeResetPhase phase) {
            if (phase == CraneEpisodeResetPhase.BeforePhysics) nextPublishTime = 0;
        }

        private void FixedUpdate() {
            if (body == null || ros == null) return;
            // BeginMeasurement resets the clock without dispatching body-reset callbacks.
            // Publication deadlines belong to an episode and cannot survive that reset.
            if (publisherEpisodeId != CraneRuntimeMetrics.EpisodeId) {
                publisherEpisodeId = CraneRuntimeMetrics.EpisodeId;
                nextPublishTime = 0;
            }
            double simulationTime = Clock.time;
            if (simulationTime + 1e-9 < nextPublishTime) return;
            // Advance by periods instead of assigning time + period, retaining fractional sensor
            // cadence at rates that do not divide the fixed 0.02-second physics interval.
            do nextPublishTime += publishPeriod;
            while (nextPublishTime <= simulationTime + 1e-9);
            Publish(simulationTime);
        }

        private void Publish(double simulationTime) {
            // Runtime fixtures may mount sensors from another sceneLoaded callback. Retry until
            // every requested static child exists instead of depending on callback order.
            if (childFrames.Count < requestedChildFrameNames.Length)
                CacheChildFrames(requestedChildFrameNames);
            HeaderMsg header = CreateHeader(simulationTime, odometryFrame);
            PointMsg position = ToRosPoint(body.position);
            Quaternion frameRotation = useRoboBoatFrame
                ? RoboBoatRosFrame.Rotation(body.rotation)
                : body.rotation;
            QuaternionMsg orientation = frameRotation.To<FLU>();
            Vector3 localLinear = body.transform.InverseTransformDirection(body.linearVelocity);
            Vector3 localAngular = body.transform.InverseTransformDirection(body.angularVelocity);
            if (useRoboBoatFrame) {
                localLinear = RoboBoatRosFrame.ToRosLocalUnity(localLinear);
                localAngular = RoboBoatRosFrame.ToRosLocalUnity(localAngular);
            }
            Vector3Msg linear = ToRosVector(localLinear);
            Vector3Msg angular = ToRosAngularVector(localAngular);

            var odometry = new OdometryMsg {
                header = header,
                child_frame_id = baseFrame
            };
            odometry.pose.pose.position = position;
            odometry.pose.pose.orientation = orientation;
            odometry.twist.twist.linear = linear;
            odometry.twist.twist.angular = angular;

            var rootTransform = new TransformStampedMsg {
                header = CreateHeader(simulationTime, odometryFrame),
                child_frame_id = baseFrame
            };
            rootTransform.transform.translation = new Vector3Msg(position.x, position.y, position.z);
            rootTransform.transform.rotation = orientation;

            var transforms = new TransformStampedMsg[childFrames.Count + 1];
            transforms[0] = rootTransform;
            for (int i = 0; i < childFrames.Count; i++) {
                Transform child = childFrames[i];
                Vector3 localPosition = useRoboBoatFrame
                    ? RoboBoatRosFrame.WorldPointToRosLocal(
                        body.position, body.rotation, child.position)
                    : body.transform.InverseTransformPoint(child.position);
                Quaternion localRotation = Quaternion.Inverse(frameRotation) * child.rotation;
                var childTransform = new TransformStampedMsg {
                    header = CreateHeader(simulationTime, baseFrame),
                    child_frame_id = child.name
                };
                childTransform.transform.translation = ToRosVector(localPosition);
                childTransform.transform.rotation = localRotation.To<FLU>();
                transforms[i + 1] = childTransform;
            }

            ros.Publish(odometryTopic, odometry);
            ros.Publish(transformTopic, new TFMessageMsg(transforms));
        }

        internal static PointMsg ToRosPoint(Vector3 unity) =>
            new(unity.z, -unity.x, unity.y);

        internal static Vector3Msg ToRosVector(Vector3 unity) =>
            new(unity.z, -unity.x, unity.y);

        // Unity-to-FLU is a handedness-changing reflection. Angular velocity is an axial vector,
        // so it gains the determinant sign that polar position/linear-velocity vectors do not.
        internal static Vector3Msg ToRosAngularVector(Vector3 unity) =>
            new(-unity.z, unity.x, -unity.y);

        private static HeaderMsg CreateHeader(double seconds, string frame) {
            double integral = Math.Floor(Math.Max(0, seconds));
            uint nanoseconds = (uint)Math.Round((Math.Max(0, seconds) - integral) * 1e9);
            if (nanoseconds >= 1_000_000_000) {
                integral += 1;
                nanoseconds = 0;
            }
            return new HeaderMsg { frame_id = frame, stamp = new TimeMsg((int)integral, nanoseconds) };
        }
    }

    internal static class CraneROSNavigationStateBootstrap {
        private static bool enabled;
        private static string odometryTopic;
        private static string transformTopic;
        private static string odometryFrame;
        private static string baseFrame;
        private static float publishRate;
        private static string[] childFrames;

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
        private static void Install() {
            string[] args = Environment.GetCommandLineArgs();
            enabled = Array.IndexOf(args, "--crane-ros-nav-state") >= 0 &&
                      !ROSPublisher.TransportSuppressed;
            if (!enabled) return;
            odometryTopic = ReadString(args, "--crane-ros-odom-topic", "/crane/odom");
            transformTopic = ReadString(args, "--crane-ros-tf-topic", "/tf");
            odometryFrame = ReadString(args, "--crane-ros-odom-frame", "odom");
            baseFrame = ReadString(args, "--crane-ros-base-frame", "base_link");
            publishRate = ReadFloat(args, "--crane-ros-nav-state-hz", 50f);
            string rawChildFrames = ReadString(args, "--crane-ros-nav-child-frames",
                "lidar_link,front_camera_link,imu_link,gps_link");
            childFrames = string.Equals(rawChildFrames, "none", StringComparison.OrdinalIgnoreCase)
                ? Array.Empty<string>()
                : rawChildFrames.Split(',', StringSplitOptions.RemoveEmptyEntries);
            for (int i = 0; i < childFrames.Length; i++) childFrames[i] = childFrames[i].Trim();
            SceneManager.sceneLoaded += OnSceneLoaded;
        }

        private static void OnSceneLoaded(Scene scene, LoadSceneMode mode) {
            if (!enabled) return;
            OmniXController controller = UnityEngine.Object.FindAnyObjectByType<OmniXController>(
                FindObjectsInactive.Exclude);
            Component body = null;
            if (controller != null) {
                body = controller.GetComponent<ArticulationBody>();
                body ??= controller.GetComponentInParent<ArticulationBody>();
                body ??= controller.GetComponent<Rigidbody>();
                body ??= controller.GetComponentInParent<Rigidbody>();
            }
            if (body == null) {
                foreach (MonoBehaviour candidate in UnityEngine.Object.FindObjectsByType<MonoBehaviour>(
                             FindObjectsInactive.Exclude)) {
                    string typeName = candidate.GetType().FullName;
                    if (typeName != "Sim.Physics.Land.AckermannRoverDynamics" &&
                        typeName != "Sim.Physics.Land.DifferentialDriveDynamics") continue;
                    body = candidate.GetComponent<Rigidbody>() ??
                           candidate.GetComponentInParent<Rigidbody>();
                    if (body != null) break;
                }
            }
            if (body == null) {
                Debug.LogWarning($"CRANE_ROS_NAV_STATE_UNAVAILABLE scene={scene.name} " +
                                 "reason=no-supported-enabled-physics-body");
                return;
            }
            var state = body.GetComponent<CraneROSNavigationState>() ??
                        body.gameObject.AddComponent<CraneROSNavigationState>();
            state.Initialize(body, odometryTopic, transformTopic, odometryFrame, baseFrame,
                publishRate, childFrames, correctRoboBoatBow: controller != null);
        }

        private static string ReadString(string[] args, string key, string fallback) {
            int index = Array.IndexOf(args, key);
            return index >= 0 && index + 1 < args.Length && !args[index + 1].StartsWith("-")
                ? args[index + 1] : fallback;
        }

        private static float ReadFloat(string[] args, string key, float fallback) {
            string raw = ReadString(args, key, null);
            return float.TryParse(raw, NumberStyles.Float, CultureInfo.InvariantCulture,
                out float value) ? value : fallback;
        }
    }
}

using UnityEngine;

// Useful for testing physical boat interfaces like ros2_control
namespace Sim.Controllers {
    public interface IControllerBase {
        void SetMotion(Vector3 linear, Vector3 angular);
    }
}

using UnityEngine;
using Sim.Actuators.Motors;
using UnityEngine.InputSystem;

namespace Sim.Controllers {
    public class OmniXController : MonoBehaviour, IControllerBase {
        [SerializeField] private InputActionReference linearAction, angularAction;
        private Vector2 linearInput;
        private float angularInput;
        public ThrusterConfig config; // Assumes all thrusters have this configuration
        public Thruster frontLeft, frontRight, rearLeft, rearRight;
        public bool movementOverride = false;

        private void OnEnable() {
            linearAction.action.performed += OnLinearPerformed;
            linearAction.action.canceled += OnLinearCanceled;

            angularAction.action.performed += OnAngularPerformed;
            angularAction.action.canceled += OnAngularCanceled;

            linearAction.action.Enable();
            angularAction.action.Enable();
        }

        private void OnDisable() {
            linearAction.action.performed -= OnLinearPerformed;
            linearAction.action.canceled -= OnLinearCanceled;

            angularAction.action.performed -= OnAngularPerformed;
            angularAction.action.canceled -= OnAngularCanceled;

            linearAction.action.Disable();
            angularAction.action.Disable();
        }

        private void OnLinearPerformed(InputAction.CallbackContext ctx) {
            movementOverride = true;
            linearInput = ctx.ReadValue<Vector2>();
            Move();
        }

        private void OnLinearCanceled(InputAction.CallbackContext ctx) {
            movementOverride = false;
            linearInput = Vector2.zero;
            Move();
        }

        private void OnAngularPerformed(InputAction.CallbackContext ctx) {
            movementOverride = true;
            angularInput = ctx.ReadValue<float>();
            Move();
        }

        private void OnAngularCanceled(InputAction.CallbackContext ctx) {
            movementOverride = false;
            angularInput = 0;
            Move();
        }

        private void Move() {
            SetMotion(new Vector3(linearInput.x, linearInput.y, 0), new Vector3(0, 0, angularInput));
        }

        // TODO: More accurately model desired linear and angular velocity (not just full forward throttle/backward/angular)
        public void SetMotion(Vector3 linear, Vector3 angular) {
            float maximum = config.GetMaxCommand();
            float x = linear.x;
            float y = linear.y;
            float yaw = angular.z;

            // Combine translation and yaw before saturation. The previous mutually exclusive
            // branches discarded Nav2 forward velocity whenever angular.z was non-zero, making
            // curved paths impossible.
            float fl = -x - y - yaw;
            float fr = x - y + yaw;
            float rl = -x + y + yaw;
            float rr = x + y - yaw;
            float peak = Mathf.Max(1f, Mathf.Abs(fl), Mathf.Abs(fr), Mathf.Abs(rl),
                Mathf.Abs(rr));
            float scale = maximum / peak;

            frontLeft.SetCommand(fl * scale);
            frontRight.SetCommand(fr * scale);
            rearLeft.SetCommand(rl * scale);
            rearRight.SetCommand(rr * scale);
        }
    }
}

using System;
using System.Globalization;
using System.Threading;
using RosMessageTypes.Geometry;
using Sim.Utils;
using Sim.Utils.Performance;
using Sim.Utils.ROS;
using UnityEngine;
using UnityEngine.SceneManagement;

namespace Sim.Controllers {
    /// <summary>
    /// Fixed-step ROS command adapter for the production Omni-X aquatic controller. Transport
    /// callbacks only enqueue immutable data; actuator commands change in FixedUpdate.
    /// </summary>
    public sealed class ROSOmniXCommand : MonoBehaviour, ICraneEpisodeResettable {
        private readonly struct Command {
            public readonly float Forward;
            public readonly float Lateral;
            public readonly float Yaw;

            public Command(float forward, float lateral, float yaw) {
                Forward = forward;
                Lateral = lateral;
                Yaw = yaw;
            }
        }

        private readonly CraneQueuedAction<Command> pending = new(command =>
            CraneActionPayloadEncoding.Float32Array(new[] {
                command.Forward, command.Lateral, command.Yaw
            }));
        private OmniXController controller;
        private IPhysicsBody body;
        private string topic;
        private float linearScale;
        private float yawScale;
        private float linearFeedForward;
        private float yawFeedForward;
        private float linearProportionalGain;
        private float yawProportionalGain;
        private float linearIntegralGain;
        private float linearIntegralEffortLimit;
        private float forwardIntegralEffort;
        private float lateralIntegralEffort;
        private float previousForwardDesired;
        private float previousLateralDesired;
        private Command desiredVelocity;
        private bool hasDesiredVelocity;
        private long sequence;
        private long lastApplicationTick = -1;
        private long timeoutTicks;
        private bool stoppedForTimeout;

        public int ResetPriority => -40;

        public void Initialize(OmniXController target, string commandTopic,
            float maximumLinearVelocity, float maximumYawRate, long commandTimeoutTicks,
            float linearVelocityFeedForward, float yawRateFeedForward,
            float linearVelocityProportionalGain, float yawRateProportionalGain,
            float linearVelocityIntegralGain, float linearVelocityIntegralEffortLimit) {
            controller = target ?? throw new ArgumentNullException(nameof(target));
            var articulation = controller.GetComponent<ArticulationBody>() ??
                               controller.GetComponentInParent<ArticulationBody>();
            var rigidbody = controller.GetComponent<Rigidbody>() ??
                            controller.GetComponentInParent<Rigidbody>();
            body = articulation != null ? new ArticulationBodyAdapter(articulation) :
                   rigidbody != null ? new RigidbodyAdapter(rigidbody) :
                   throw new MissingComponentException(
                       $"{controller.name} requires a physics body for velocity feedback");
            topic = commandTopic;
            linearScale = Mathf.Max(0.0001f, maximumLinearVelocity);
            yawScale = Mathf.Max(0.0001f, maximumYawRate);
            linearFeedForward = Mathf.Max(0f, linearVelocityFeedForward);
            yawFeedForward = Mathf.Max(0f, yawRateFeedForward);
            linearProportionalGain = Mathf.Max(0f, linearVelocityProportionalGain);
            yawProportionalGain = Mathf.Max(0f, yawRateProportionalGain);
            linearIntegralGain = Mathf.Max(0f, linearVelocityIntegralGain);
            linearIntegralEffortLimit = Mathf.Clamp01(linearVelocityIntegralEffortLimit);
            timeoutTicks = Math.Max(1, commandTimeoutTicks);
            var subscriber = gameObject.AddComponent<ROSSubscriber>();
            subscriber.Initialize<TwistStampedMsg>(topic, Receive);
            Debug.Log($"CRANE_ROS_COMMAND_READY topic={topic} controller={controller.name} " +
                      $"linearScale={linearScale:R} yawScale={yawScale:R} " +
                      $"linearFeedForward={linearFeedForward:R} " +
                      $"yawFeedForward={yawFeedForward:R} " +
                      $"linearKp={linearProportionalGain:R} yawKp={yawProportionalGain:R} " +
                      $"linearKi={linearIntegralGain:R} " +
                      $"linearIntegralLimit={linearIntegralEffortLimit:R} " +
                      $"timeoutTicks={timeoutTicks}");
        }

        public void CaptureEpisodeInitialState() { }

        public void ResetEpisode(in CraneEpisodeResetContext context,
            CraneEpisodeResetPhase phase) {
            if (phase != CraneEpisodeResetPhase.BeforePhysics) return;
            pending.Clear("episode_reset_before_physics");
            sequence = 0;
            lastApplicationTick = -1;
            stoppedForTimeout = false;
            ResetLinearIntegral();
            Stop();
        }

        private void Receive(TwistStampedMsg message) {
            if (message?.twist == null || message.header?.stamp == null) return;
            double seconds = message.header.stamp.sec + message.header.stamp.nanosec * 1e-9;
            long sourceTick = seconds < 0 ? -1 :
                (long)Math.Round(seconds / Time.fixedDeltaTime, MidpointRounding.AwayFromZero);
            var command = new Command(
                Mathf.Clamp((float)message.twist.linear.x, -linearScale, linearScale),
                Mathf.Clamp((float)message.twist.linear.y, -linearScale, linearScale),
                Mathf.Clamp((float)message.twist.angular.z, -yawScale, yawScale));
            long commandSequence = Interlocked.Increment(ref sequence);
            if (CraneActionTimingAudit.Enabled) {
                CraneActionTimingAudit.RecordRosCallback($"ros:{topic}", commandSequence, sourceTick,
                    message.header.stamp.sec, message.header.stamp.nanosec);
            }
            pending.Receive(command, $"ros:{topic}", commandSequence, sourceTick);
        }

        private void FixedUpdate() {
            if (controller == null) return;
            if (controller.movementOverride) {
                pending.Clear("movement_override");
                hasDesiredVelocity = false;
                ResetLinearIntegral();
                return;
            }
            if (pending.TryApply(SetDesiredVelocity, out _)) {
                lastApplicationTick = CraneRuntimeMetrics.SimulationTick;
                stoppedForTimeout = false;
            }
            else if (!stoppedForTimeout && lastApplicationTick >= 0 &&
                     CraneRuntimeMetrics.SimulationTick - lastApplicationTick > timeoutTicks) {
                Stop();
                stoppedForTimeout = true;
                CraneRuntimeMetrics.ReportCommandTimeout();
                Debug.LogWarning($"CRANE_ROS_COMMAND_TIMEOUT topic={topic} " +
                                 $"lastApplicationTick={lastApplicationTick}");
            }
            if (hasDesiredVelocity) ApplyVelocityControl();
        }

        private void SetDesiredVelocity(Command command) {
            desiredVelocity = command;
            hasDesiredVelocity = true;
        }

        private void ApplyVelocityControl() {
            Vector3 localLinear = RoboBoatRosFrame.ToRosLocalUnity(
                body.transform.InverseTransformDirection(body.linearVelocity));
            Vector3 localAngular = RoboBoatRosFrame.ToRosLocalUnity(
                body.transform.InverseTransformDirection(body.angularVelocity));
            float measuredForward = localLinear.z;
            float measuredLateral = -localLinear.x;
            float measuredYaw = -localAngular.y;
            UpdateNormalizedLinearIntegral(desiredVelocity.Forward, measuredForward, linearScale,
                linearIntegralGain, linearIntegralEffortLimit, Time.fixedDeltaTime,
                ref forwardIntegralEffort, ref previousForwardDesired);
            UpdateNormalizedLinearIntegral(desiredVelocity.Lateral, measuredLateral, linearScale,
                linearIntegralGain, linearIntegralEffortLimit, Time.fixedDeltaTime,
                ref lateralIntegralEffort, ref previousLateralDesired);
            var effort = new Command(
                Mathf.Clamp(CalculateNormalizedLinearEffort(
                    desiredVelocity.Forward, measuredForward, linearScale,
                    linearFeedForward, linearProportionalGain) + forwardIntegralEffort, -1f, 1f),
                Mathf.Clamp(CalculateNormalizedLinearEffort(
                    desiredVelocity.Lateral, measuredLateral, linearScale,
                    linearFeedForward, linearProportionalGain) + lateralIntegralEffort, -1f, 1f),
                CalculateNormalizedYawEffort(desiredVelocity.Yaw, measuredYaw, yawScale,
                    yawFeedForward, yawProportionalGain));
            ToControllerMotion(effort.Forward, effort.Lateral, effort.Yaw,
                out Vector3 linear, out Vector3 angular);
            controller.SetMotion(linear, angular);
        }

        private void Stop() {
            desiredVelocity = new Command(0f, 0f, 0f);
            hasDesiredVelocity = false;
            ResetLinearIntegral();
            controller.SetMotion(Vector3.zero, Vector3.zero);
        }

        private void ResetLinearIntegral() {
            forwardIntegralEffort = 0f;
            lateralIntegralEffort = 0f;
            previousForwardDesired = 0f;
            previousLateralDesired = 0f;
        }

        internal static float CalculateNormalizedLinearEffort(float desired, float measured,
            float scale, float feedForward, float proportionalGain) {
            float normalizedDesired = desired / Mathf.Max(0.0001f, scale);
            float normalizedError = (desired - measured) / Mathf.Max(0.0001f, scale);
            float modelEffort = feedForward * normalizedDesired;
            return Mathf.Clamp(modelEffort + proportionalGain * normalizedError, -1f, 1f);
        }

        internal static float CalculateNormalizedYawEffort(float desired, float measured,
            float scale, float feedForward, float proportionalGain) {
            float normalizedDesired = desired / Mathf.Max(0.0001f, scale);
            float normalizedError = (desired - measured) / Mathf.Max(0.0001f, scale);
            float modelEffort = Mathf.Sign(normalizedDesired) * feedForward *
                                Mathf.Sqrt(Mathf.Abs(normalizedDesired));
            return Mathf.Clamp(modelEffort + proportionalGain * normalizedError, -1f, 1f);
        }

        internal static void UpdateNormalizedLinearIntegral(float desired, float measured,
            float scale, float integralGain, float integralEffortLimit, float deltaTime,
            ref float integralEffort, ref float previousDesired) {
            if (Mathf.Abs(desired) < 0.0001f || desired * previousDesired < 0f) {
                integralEffort = 0f;
            }
            else {
                float normalizedError = (desired - measured) / Mathf.Max(0.0001f, scale);
                integralEffort = Mathf.Clamp(
                    integralEffort + integralGain * normalizedError * Mathf.Max(0f, deltaTime),
                    -Mathf.Abs(integralEffortLimit), Mathf.Abs(integralEffortLimit));
            }
            previousDesired = desired;
        }

        internal static void ToControllerMotion(float forward, float lateral, float yaw,
            out Vector3 linear, out Vector3 angular) {
            // The imported catamaran's visible bow is body-local -X (the chase camera is aft at
            // +X), while OmniX controller X realizes body-local +Z and controller Y realizes
            // body-local -X. Keep this correction at the ROS boundary so manual input, the mixer,
            // and the physical model retain their established contract.
            linear = new Vector3(-lateral, forward, 0f);
            angular = new Vector3(0f, 0f, -yaw);
        }
    }

    /// <summary>
    /// Defines the ROS FLU body frame from the imported RoboBoat physics transform. The model's
    /// visible bow is physics-local -X, so the ROS-frame Unity-forward axis is rotated -90 degrees
    /// about Unity up relative to the ArticulationBody transform.
    /// </summary>
    internal static class RoboBoatRosFrame {
        private static readonly Quaternion BodyFromRos = Quaternion.Euler(0f, -90f, 0f);
        private static readonly Quaternion RosFromBody = Quaternion.Inverse(BodyFromRos);

        internal static Quaternion Rotation(Quaternion bodyRotation) =>
            bodyRotation * BodyFromRos;

        internal static Vector3 ToRosLocalUnity(Vector3 bodyLocal) =>
            RosFromBody * bodyLocal;

        internal static Vector3 WorldPointToRosLocal(Vector3 bodyPosition,
            Quaternion bodyRotation, Vector3 worldPoint) =>
            Quaternion.Inverse(Rotation(bodyRotation)) * (worldPoint - bodyPosition);
    }

    internal static class ROSOmniXCommandBootstrap {
        private static string topic;
        private static float linearScale;
        private static float yawScale;
        private static long timeoutTicks;
        private static float linearFeedForward;
        private static float yawFeedForward;
        private static float linearProportionalGain;
        private static float yawProportionalGain;
        private static float linearIntegralGain;
        private static float linearIntegralEffortLimit;
        private static bool enabled;

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
        private static void Initialize() {
            string[] args = Environment.GetCommandLineArgs();
            int flag = Array.IndexOf(args, "--crane-ros-cmd-vel");
            enabled = flag >= 0 && !ROSPublisher.TransportSuppressed;
            if (!enabled) return;
            topic = flag + 1 < args.Length && !args[flag + 1].StartsWith("-") ?
                args[flag + 1] : "/crane/cmd_vel_stamped";
            linearScale = ReadFloat(args, "--crane-cmd-vel-linear-scale", 1f);
            yawScale = ReadFloat(args, "--crane-cmd-vel-yaw-scale", 1f);
            linearFeedForward = ReadFloat(args, "--crane-cmd-vel-linear-feed-forward", 0.21f);
            yawFeedForward = ReadFloat(args, "--crane-cmd-vel-yaw-feed-forward", 0.24f);
            linearProportionalGain = ReadFloat(args, "--crane-cmd-vel-linear-kp", 0.1f);
            yawProportionalGain = ReadFloat(args, "--crane-cmd-vel-yaw-kp", 0.05f);
            linearIntegralGain = ReadFloat(args, "--crane-cmd-vel-linear-ki", 0.1f);
            linearIntegralEffortLimit = ReadFloat(
                args, "--crane-cmd-vel-linear-integral-limit", 0.2f);
            timeoutTicks = ReadLong(args, "--crane-command-timeout-ticks", 25);
            SceneManager.sceneLoaded += OnSceneLoaded;
        }

        private static void OnSceneLoaded(Scene scene, LoadSceneMode mode) {
            if (!enabled) return;
            OmniXController controller = UnityEngine.Object.FindAnyObjectByType<OmniXController>(
                FindObjectsInactive.Exclude);
            if (controller == null) {
                Debug.LogWarning($"CRANE_ROS_COMMAND_UNAVAILABLE scene={scene.name} " +
                                 "reason=no-enabled-omni-x-controller");
                return;
            }
            var adapter = controller.gameObject.GetComponent<ROSOmniXCommand>() ??
                controller.gameObject.AddComponent<ROSOmniXCommand>();
            adapter.Initialize(controller, topic, linearScale, yawScale, timeoutTicks,
                linearFeedForward, yawFeedForward, linearProportionalGain,
                yawProportionalGain, linearIntegralGain, linearIntegralEffortLimit);
        }

        private static float ReadFloat(string[] args, string key, float fallback) {
            int index = Array.IndexOf(args, key);
            return index >= 0 && index + 1 < args.Length && float.TryParse(args[index + 1],
                NumberStyles.Float, CultureInfo.InvariantCulture, out float value) ? value : fallback;
        }

        private static long ReadLong(string[] args, string key, long fallback) {
            int index = Array.IndexOf(args, key);
            return index >= 0 && index + 1 < args.Length && long.TryParse(args[index + 1],
                NumberStyles.Integer, CultureInfo.InvariantCulture, out long value) ? value : fallback;
        }
    }
}

using System;
using UnityEngine;
using Sim.Utils.Performance;

namespace Sim.Physics.Land {
    /// <summary>
    /// Four-wheel Ackermann rover backed by PhysX WheelColliders. Commands are normalized;
    /// ordinary motion is produced only through wheel torque, steering, braking, and contact.
    /// </summary>
    [RequireComponent(typeof(Rigidbody))]
    public sealed class AckermannRoverDynamics : MonoBehaviour, ICraneEpisodeResettable {
        [Header("Wheel references")]
        [SerializeField] private WheelCollider frontLeft;
        [SerializeField] private WheelCollider frontRight;
        [SerializeField] private WheelCollider rearLeft;
        [SerializeField] private WheelCollider rearRight;

        [Header("Geometry and limits")]
        [SerializeField] private float wheelbase = 1.6f;
        [SerializeField] private float trackWidth = 1.2f;
        [SerializeField] private float maximumSteeringAngle = 32f;
        [SerializeField] private float maximumMotorTorque = 6f;
        [SerializeField] private float maximumBrakeTorque = 650f;
        [SerializeField] private float maximumSpeed = 12f;

        [Header("Actuator and resistance")]
        [SerializeField] private float motorTimeConstant = 0.18f;
        [SerializeField] private float steeringRateDegreesPerSecond = 90f;
        [SerializeField, Range(0f, 0.1f)] private float rollingResistanceCoefficient = 0.015f;

        private Rigidbody body;
        private float throttleCommand;
        private float steeringCommand;
        private float brakeCommand;
        private float appliedTorque;
        private float leftSteeringAngle;
        private float rightSteeringAngle;
        private WheelCollider[] wheels;
        public int ResetPriority => -40;
        public void CaptureEpisodeInitialState() { }
        public void ResetEpisode(in CraneEpisodeResetContext context,
            CraneEpisodeResetPhase phase) {
            if (phase == CraneEpisodeResetPhase.BeforePhysics) ResetActuators();
        }

        public float Speed => Vector3.Dot(body.linearVelocity, transform.forward);
        public float ThrottleCommand => throttleCommand;
        public float SteeringCommand => steeringCommand;
        public float BrakeCommand => brakeCommand;
        public float AppliedWheelTorque => appliedTorque;
        public float LeftSteeringAngle => leftSteeringAngle;
        public float RightSteeringAngle => rightSteeringAngle;
        public float Wheelbase => wheelbase;
        public float TrackWidth => trackWidth;
        public float MaximumSteeringAngle => maximumSteeringAngle;
        public int GroundedWheelCount {
            get {
                int count = 0;
                foreach (WheelCollider wheel in wheels)
                    if (wheel.isGrounded) count++;
                return count;
            }
        }
        public float AverageWheelRpm {
            get {
                float rpm = 0f;
                foreach (WheelCollider wheel in wheels) rpm += Mathf.Abs(wheel.rpm);
                return rpm / wheels.Length;
            }
        }

        private void Awake() {
            body = GetComponent<Rigidbody>();
            ValidateWheels();
            CacheWheels();
        }

        public void Configure(WheelCollider fl, WheelCollider fr, WheelCollider rl,
            WheelCollider rr, float configuredWheelbase, float configuredTrackWidth) {
            frontLeft = fl;
            frontRight = fr;
            rearLeft = rl;
            rearRight = rr;
            wheelbase = configuredWheelbase;
            trackWidth = configuredTrackWidth;
            CacheWheels();
        }

        public void SetCommand(float throttle, float steering, float brake) {
            throttleCommand = Mathf.Clamp(throttle, -1f, 1f);
            steeringCommand = Mathf.Clamp(steering, -1f, 1f);
            brakeCommand = Mathf.Clamp01(brake);
        }

        private void FixedUpdate() {
            UpdateSteering();
            UpdateMotor();
            ApplyWheelCommands();
        }

        private void UpdateSteering() {
            float targetLeft = 0f;
            float targetRight = 0f;
            float targetCenter = steeringCommand * maximumSteeringAngle;
            if (Mathf.Abs(targetCenter) > 0.01f) {
                float sign = Mathf.Sign(targetCenter);
                float centerRadians = Mathf.Abs(targetCenter) * Mathf.Deg2Rad;
                float centerRadius = wheelbase / Mathf.Tan(centerRadians);
                float inner = Mathf.Atan(wheelbase / Mathf.Max(0.05f,
                    centerRadius - trackWidth * 0.5f)) * Mathf.Rad2Deg;
                float outer = Mathf.Atan(wheelbase / (centerRadius + trackWidth * 0.5f)) * Mathf.Rad2Deg;
                if (sign > 0) { targetLeft = inner; targetRight = outer; }
                else { targetLeft = -outer; targetRight = -inner; }
            }
            float maxChange = steeringRateDegreesPerSecond * Time.fixedDeltaTime;
            leftSteeringAngle = Mathf.MoveTowards(leftSteeringAngle, targetLeft, maxChange);
            rightSteeringAngle = Mathf.MoveTowards(rightSteeringAngle, targetRight, maxChange);
        }

        private void UpdateMotor() {
            float targetTorque = throttleCommand * maximumMotorTorque;
            if (Mathf.Abs(Speed) >= maximumSpeed && Mathf.Sign(targetTorque) == Mathf.Sign(Speed))
                targetTorque = 0f;
            float response = motorTimeConstant <= 0f ? 1f :
                1f - Mathf.Exp(-Time.fixedDeltaTime / motorTimeConstant);
            appliedTorque = Mathf.Lerp(appliedTorque, targetTorque, response);
        }

        private void ApplyWheelCommands() {
            frontLeft.steerAngle = leftSteeringAngle;
            frontRight.steerAngle = rightSteeringAngle;
            float rollingTorque = rollingResistanceCoefficient * body.mass *
                UnityEngine.Physics.gravity.magnitude * frontLeft.radius / wheels.Length;
            float brakeTorque = brakeCommand * maximumBrakeTorque;
            if (Mathf.Abs(throttleCommand) < 0.001f && brakeCommand <= 0f)
                brakeTorque = rollingTorque;
            foreach (WheelCollider wheel in wheels) {
                wheel.motorTorque = appliedTorque;
                wheel.brakeTorque = brakeTorque;
            }
        }

        public float ExpectedCenterTurnRadius(float normalizedSteering) {
            float angle = Mathf.Abs(normalizedSteering) * maximumSteeringAngle * Mathf.Deg2Rad;
            return angle <= 0.0001f ? float.PositiveInfinity : wheelbase / Mathf.Tan(angle);
        }

        public void ResetActuators() {
            throttleCommand = steeringCommand = brakeCommand = appliedTorque = 0f;
            leftSteeringAngle = rightSteeringAngle = 0f;
            ApplyWheelCommands();
        }

        private void ValidateWheels() {
            if (frontLeft == null || frontRight == null || rearLeft == null || rearRight == null)
                throw new MissingReferenceException($"{name} requires four WheelColliders.");
        }

        private void CacheWheels() {
            wheels = new[] { frontLeft, frontRight, rearLeft, rearRight };
        }
    }
}

using UnityEngine;
using Sim.Utils.Performance;

namespace Sim.Physics.Land {
    /// <summary>
    /// Force-driven planar differential base. Commands are body linear/angular velocities;
    /// movement remains subject to PhysX mass, contact, friction, and canonical colliders.
    /// </summary>
    [RequireComponent(typeof(Rigidbody))]
    public sealed class DifferentialDriveDynamics : MonoBehaviour, ICraneEpisodeResettable {
        [SerializeField] private float wheelSeparation = 0.287f;
        [SerializeField] private float wheelRadius = 0.033f;
        [SerializeField] private float maximumLinearSpeed = 0.26f;
        [SerializeField] private float maximumAngularSpeed = 1.82f;
        [SerializeField] private float maximumLinearAcceleration = 10.0f;
        [SerializeField] private float maximumAngularAcceleration = 6.0f;

        private Rigidbody body;
        private float commandedLinear;
        private float commandedAngular;

        public int ResetPriority => -40;
        public float WheelSeparation => wheelSeparation;
        public float WheelRadius => wheelRadius;
        public float MaximumLinearSpeed => maximumLinearSpeed;
        public float MaximumAngularSpeed => maximumAngularSpeed;

        private void Awake() => body = GetComponent<Rigidbody>();

        public void Configure(float separation, float radius, float linearSpeed,
            float angularSpeed) {
            wheelSeparation = Mathf.Max(0.01f, separation);
            wheelRadius = Mathf.Max(0.001f, radius);
            maximumLinearSpeed = Mathf.Max(0.01f, linearSpeed);
            maximumAngularSpeed = Mathf.Max(0.01f, angularSpeed);
            maximumLinearAcceleration = 10.0f;
            maximumAngularAcceleration = 6.0f;
        }

        public void SetCommand(float linear, float angular) {
            commandedLinear = Mathf.Clamp(linear, -maximumLinearSpeed, maximumLinearSpeed);
            commandedAngular = Mathf.Clamp(angular, -maximumAngularSpeed, maximumAngularSpeed);
        }

        private void FixedUpdate() {
            Vector3 localVelocity = transform.InverseTransformDirection(body.linearVelocity);
            float linearError = commandedLinear - localVelocity.z;
            float linearDelta = Mathf.Clamp(linearError,
                -maximumLinearAcceleration * Time.fixedDeltaTime,
                maximumLinearAcceleration * Time.fixedDeltaTime);
            body.AddForce(transform.forward * linearDelta, ForceMode.VelocityChange);
            float angularError = commandedAngular - body.angularVelocity.y;
            float angularDelta = Mathf.Clamp(angularError,
                -maximumAngularAcceleration * Time.fixedDeltaTime,
                maximumAngularAcceleration * Time.fixedDeltaTime);
            body.AddTorque(Vector3.up * angularDelta, ForceMode.VelocityChange);
            // The physical platform is non-holonomic; cancel lateral numerical drift without
            // changing forward or vertical dynamics.
            float lateralDelta = Mathf.Clamp(-localVelocity.x,
                -maximumLinearAcceleration * Time.fixedDeltaTime,
                maximumLinearAcceleration * Time.fixedDeltaTime);
            body.AddForce(transform.right * lateralDelta, ForceMode.VelocityChange);
        }

        public void CaptureEpisodeInitialState() { }

        public void ResetEpisode(in CraneEpisodeResetContext context,
            CraneEpisodeResetPhase phase) {
            if (phase == CraneEpisodeResetPhase.BeforePhysics) SetCommand(0f, 0f);
        }
    }
}

using System;
using System.Globalization;
using System.Threading;
using RosMessageTypes.Geometry;
using Sim.Utils.Performance;
using Sim.Utils.ROS;
using UnityEngine;
using UnityEngine.SceneManagement;

namespace Sim.Physics.Land {
    /// <summary>Applies stamped ROS velocity commands to the PhysX Ackermann rover.</summary>
    public sealed class ROSAckermannCommand : MonoBehaviour, ICraneEpisodeResettable {
        private readonly struct Command {
            public readonly float Linear;
            public readonly float Angular;
            public Command(float linear, float angular) { Linear = linear; Angular = angular; }
        }

        private readonly CraneQueuedAction<Command> pending = new(command =>
            CraneActionPayloadEncoding.Float32Array(new[] { command.Linear, command.Angular }));
        private AckermannRoverDynamics rover;
        private string topic;
        private float maximumLinearSpeed;
        private long timeoutTicks;
        private long sequence;
        private long lastApplicationTick = -1;
        private bool stoppedForTimeout;

        public int ResetPriority => -40;

        public void Initialize(AckermannRoverDynamics target, string commandTopic,
            float linearSpeed, long commandTimeoutTicks) {
            rover = target ?? throw new ArgumentNullException(nameof(target));
            topic = commandTopic;
            maximumLinearSpeed = Mathf.Max(0.01f, linearSpeed);
            timeoutTicks = Math.Max(1, commandTimeoutTicks);
            var subscriber = gameObject.AddComponent<ROSSubscriber>();
            subscriber.Initialize<TwistStampedMsg>(topic, Receive);
            Debug.Log($"CRANE_ROS_ACKERMANN_COMMAND_READY topic={topic} rover={rover.name} " +
                      $"maximumLinearSpeed={maximumLinearSpeed:R} timeoutTicks={timeoutTicks}");
        }

        public void CaptureEpisodeInitialState() { }

        public void ResetEpisode(in CraneEpisodeResetContext context,
            CraneEpisodeResetPhase phase) {
            if (phase != CraneEpisodeResetPhase.BeforePhysics) return;
            pending.Clear();
            sequence = 0;
            lastApplicationTick = -1;
            stoppedForTimeout = false;
            Stop();
        }

        private void Receive(TwistStampedMsg message) {
            if (message?.twist == null || message.header?.stamp == null) return;
            double seconds = message.header.stamp.sec + message.header.stamp.nanosec * 1e-9;
            long sourceTick = seconds < 0 ? -1 :
                (long)Math.Round(seconds / Time.fixedDeltaTime, MidpointRounding.AwayFromZero);
            pending.Receive(new Command((float)message.twist.linear.x,
                    (float)message.twist.angular.z), $"ros:{topic}",
                Interlocked.Increment(ref sequence), sourceTick);
        }

        private void FixedUpdate() {
            if (rover == null) return;
            if (pending.TryApply(Apply, out _)) {
                lastApplicationTick = CraneRuntimeMetrics.SimulationTick;
                stoppedForTimeout = false;
            }
            else if (!stoppedForTimeout && lastApplicationTick >= 0 &&
                     CraneRuntimeMetrics.SimulationTick - lastApplicationTick > timeoutTicks) {
                Stop();
                stoppedForTimeout = true;
                CraneRuntimeMetrics.ReportCommandTimeout();
                Debug.LogWarning($"CRANE_ROS_ACKERMANN_COMMAND_TIMEOUT topic={topic} " +
                                 $"lastApplicationTick={lastApplicationTick}");
            }
        }

        private void Apply(Command command) {
            float linear = Mathf.Clamp(command.Linear, -maximumLinearSpeed, maximumLinearSpeed);
            if (Mathf.Abs(linear) < 0.01f) {
                Stop();
                return;
            }
            float steeringRadians = Mathf.Atan(rover.Wheelbase * command.Angular / linear);
            float steering = steeringRadians * Mathf.Rad2Deg / rover.MaximumSteeringAngle;
            rover.SetCommand(linear / maximumLinearSpeed, steering, 0f);
        }

        private void Stop() => rover.SetCommand(0f, 0f, 1f);
    }

    internal static class ROSAckermannCommandBootstrap {
        private static bool enabled;
        private static string topic;
        private static float maximumLinearSpeed;
        private static long timeoutTicks;

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
        private static void Install() {
            string[] args = Environment.GetCommandLineArgs();
            int flag = Array.IndexOf(args, "--crane-ros-ackermann-cmd-vel");
            enabled = flag >= 0 && !ROSPublisher.TransportSuppressed;
            if (!enabled) return;
            topic = flag + 1 < args.Length && !args[flag + 1].StartsWith("-")
                ? args[flag + 1] : "/crane/cmd_vel_stamped";
            maximumLinearSpeed = ReadFloat(args, "--crane-ackermann-linear-scale", 2f);
            timeoutTicks = ReadLong(args, "--crane-command-timeout-ticks", 25);
            SceneManager.sceneLoaded += OnSceneLoaded;
        }

        private static void OnSceneLoaded(Scene scene, LoadSceneMode mode) {
            if (!enabled) return;
            AckermannRoverDynamics rover = UnityEngine.Object.FindAnyObjectByType<
                AckermannRoverDynamics>(FindObjectsInactive.Exclude);
            if (rover == null) {
                Debug.LogWarning($"CRANE_ROS_ACKERMANN_COMMAND_UNAVAILABLE scene={scene.name} " +
                                 "reason=no-enabled-ackermann-rover");
                return;
            }
            var adapter = rover.GetComponent<ROSAckermannCommand>() ??
                          rover.gameObject.AddComponent<ROSAckermannCommand>();
            adapter.Initialize(rover, topic, maximumLinearSpeed, timeoutTicks);
        }

        private static float ReadFloat(string[] args, string key, float fallback) {
            int index = Array.IndexOf(args, key);
            return index >= 0 && index + 1 < args.Length && float.TryParse(args[index + 1],
                NumberStyles.Float, CultureInfo.InvariantCulture, out float value)
                ? value : fallback;
        }

        private static long ReadLong(string[] args, string key, long fallback) {
            int index = Array.IndexOf(args, key);
            return index >= 0 && index + 1 < args.Length && long.TryParse(args[index + 1],
                NumberStyles.Integer, CultureInfo.InvariantCulture, out long value)
                ? value : fallback;
        }
    }
}

using System;
