namespace Sim.Physics.Land {
    /// <summary>Applies stamped ROS velocity commands to a differential-drive base.</summary>
    public sealed class ROSDifferentialCommand : MonoBehaviour, ICraneEpisodeResettable {
        private readonly struct Command {
            public readonly float Linear;
            public readonly float Angular;
            public Command(float linear, float angular) { Linear = linear; Angular = angular; }
        }

        private readonly CraneQueuedAction<Command> pending = new(command =>
            CraneActionPayloadEncoding.Float32Array(new[] { command.Linear, command.Angular }));
        private DifferentialDriveDynamics robot;
        private string topic;
        private long timeoutTicks;
        private long sequence;
        private long lastApplicationTick = -1;
        private bool stoppedForTimeout;
        public int ResetPriority => -40;

        public void Initialize(DifferentialDriveDynamics target, string commandTopic,
            long commandTimeoutTicks) {
            robot = target ?? throw new ArgumentNullException(nameof(target));
            topic = commandTopic;
            timeoutTicks = Math.Max(1, commandTimeoutTicks);
            var subscriber = gameObject.AddComponent<ROSSubscriber>();
            subscriber.Initialize<TwistStampedMsg>(topic, Receive);
            Debug.Log($"CRANE_ROS_DIFFERENTIAL_COMMAND_READY topic={topic} robot={robot.name} " +
                      $"timeoutTicks={timeoutTicks}");
        }

        private void Receive(TwistStampedMsg message) {
            if (message?.twist == null || message.header?.stamp == null) return;
            double seconds = message.header.stamp.sec + message.header.stamp.nanosec * 1e-9;
            long sourceTick = seconds < 0 ? -1 :
                (long)Math.Round(seconds / Time.fixedDeltaTime, MidpointRounding.AwayFromZero);
            pending.Receive(new Command((float)message.twist.linear.x,
                    (float)message.twist.angular.z), $"ros:{topic}",
                Interlocked.Increment(ref sequence), sourceTick);
        }

        private void FixedUpdate() {
            if (robot == null) return;
            // ROS FLU positive yaw turns left. Unity's positive Y rotation turns +Z toward +X,
            // which is ROS right because position maps as (x, y) = (z, -x). Negate yaw at the
            // coordinate boundary so command direction agrees with the published FLU pose.
            if (pending.TryApply(command => robot.SetCommand(command.Linear, -command.Angular), out _)) {
                lastApplicationTick = CraneRuntimeMetrics.SimulationTick;
                stoppedForTimeout = false;
            }
            else if (!stoppedForTimeout && lastApplicationTick >= 0 &&
                     CraneRuntimeMetrics.SimulationTick - lastApplicationTick > timeoutTicks) {
                robot.SetCommand(0f, 0f);
                stoppedForTimeout = true;
                CraneRuntimeMetrics.ReportCommandTimeout();
            }
        }

        public void CaptureEpisodeInitialState() { }
        public void ResetEpisode(in CraneEpisodeResetContext context,
            CraneEpisodeResetPhase phase) {
            if (phase != CraneEpisodeResetPhase.BeforePhysics) return;
            pending.Clear();
            sequence = 0;
            lastApplicationTick = -1;
            stoppedForTimeout = false;
            if (robot != null) robot.SetCommand(0f, 0f);
        }
    }

    internal static class ROSDifferentialCommandBootstrap {
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
        private static void Install() {
            string[] args = Environment.GetCommandLineArgs();
            int flag = Array.IndexOf(args, "--crane-ros-differential-cmd-vel");
            if (flag < 0 || ROSPublisher.TransportSuppressed) return;
            string topic = flag + 1 < args.Length && !args[flag + 1].StartsWith("-")
                ? args[flag + 1] : "/crane/cmd_vel_stamped";
            long timeout = ReadLong(args, "--crane-command-timeout-ticks", 25);
            SceneManager.sceneLoaded += (_, _) => {
                DifferentialDriveDynamics robot = UnityEngine.Object.FindAnyObjectByType<
                    DifferentialDriveDynamics>(FindObjectsInactive.Exclude);
                if (robot == null) return;
                var adapter = robot.GetComponent<ROSDifferentialCommand>() ??
                              robot.gameObject.AddComponent<ROSDifferentialCommand>();
                adapter.Initialize(robot, topic, timeout);
            };
        }

        private static long ReadLong(string[] args, string key, long fallback) {
            int index = Array.IndexOf(args, key);
            return index >= 0 && index + 1 < args.Length && long.TryParse(args[index + 1],
                NumberStyles.Integer, CultureInfo.InvariantCulture, out long value)
                ? value : fallback;
        }
    }
}

using UnityEngine.Rendering.HighDefinition;
using System.Collections.Generic;
using Unity.Mathematics;
using Unity.Collections;
using UnityEngine;
using Unity.Jobs;
using System;
using Sim.Utils.Performance;


namespace Sim.Physics.Processing {
    public class Patch {
        // Used in Submersion.cs
        public Vector3[] patchVertices;
        public int[] patchTriangles;
        public Mesh baseGridMesh;

        // Water height querying (burst)
        // Input job parameters
        NativeArray<float3> targetPositionBuffer;

        // Output job parameters
        NativeArray<float3> projectedPositionWorldSpaceBuffer;
        NativeArray<float3> candidatePositionWorldSpaceBuffer;
        NativeArray<float3> directionBuffer;
        NativeArray<int> stepCountBuffer;
        NativeArray<float> errorBuffer;
        NativeArray<float3> normalWSBuffer;

        // OK Private
        private int numberOfGridPoints;
        private WaterSurface water;
        private Vector3 gridOrigin;
        private float sideLength;
        private int gridFidelity;
        private float cellSize;
        private Vector3[] baseGridMeshVertices;
        private int[] baseGridMeshTriangles;


        /// Populate patch variables and do initialize step
        public Patch(WaterSurface water, float sideLength, int gridFidelity, Vector3 gridOrigin) {
            this.gridFidelity = gridFidelity;
            this.gridOrigin = gridOrigin;
            this.sideLength = sideLength;
            this.water = water;
            Initialize();
        }


        /// Call patch builder and initialize buffers
        private void Initialize() {
            cellSize = sideLength / gridFidelity;
            baseGridMesh = ConstructWaterGridMesh();
            baseGridMeshVertices = baseGridMesh.vertices;
            baseGridMeshTriangles = baseGridMesh.triangles;
            patchVertices = baseGridMesh.vertices;
            patchTriangles = baseGridMesh.triangles;
            numberOfGridPoints = baseGridMesh.vertices.Length;

            // Allocate the buffers
            projectedPositionWorldSpaceBuffer = new NativeArray<float3>(numberOfGridPoints, Allocator.Persistent);
            candidatePositionWorldSpaceBuffer = new NativeArray<float3>(numberOfGridPoints, Allocator.Persistent);
            targetPositionBuffer = new NativeArray<float3>(numberOfGridPoints, Allocator.Persistent);
            directionBuffer = new NativeArray<float3>(numberOfGridPoints, Allocator.Persistent);
            stepCountBuffer = new NativeArray<int>(numberOfGridPoints, Allocator.Persistent);
            errorBuffer = new NativeArray<float>(numberOfGridPoints, Allocator.Persistent);
            normalWSBuffer = new NativeArray<float3>(numberOfGridPoints, Allocator.Persistent);
        }


        /// Burst version. Updates the patch to follow the boat in x and z and queried water height in y.
        public void Update(Transform transform) {
            SetGridOrigin(transform);

            WaterSimSearchData simData = new();
            using (CraneProfiler.WaterPrepare.Auto()) {
                if (!water.FillWaterSearchData(ref simData)) {
                    return;
                }
            }

            // Update vertex positions
            for (var i = 0; i < patchVertices.Length; i++) {
                float waterHeight = projectedPositionWorldSpaceBuffer[i].y;
                patchVertices[i].x = baseGridMeshVertices[i].x + transform.position.x;
                patchVertices[i].z = baseGridMeshVertices[i].z + transform.position.z;
                patchVertices[i].y = waterHeight;
                targetPositionBuffer[i] = patchVertices[i];
            }

            ExecuteWaterSimulationSearchJob(simData, patchVertices);
            return;
        }


        /// Run once. Creates a new mesh representing the water patch grid based on parameters from submersion script.
        private Mesh ConstructWaterGridMesh() {
            Mesh meshOut = new();
            //float vertexOffset = sideLength / gridFidelity;
            int rows = gridFidelity + 1;
            int columns = gridFidelity + 1;

            Vector3[] vertices = new Vector3[rows * columns];
            int[] triangles = new int[gridFidelity * gridFidelity * 6];

            int triangleIndex = 0;

            // Populate vertices and triangles arrays
            for (var i = 0; i < rows; i++) {
                for (var j = 0; j < columns; j++) {
                    int vertexIndex = i * columns + j;
                    vertices[vertexIndex] = gridOrigin + new Vector3(cellSize * j, 0.0f, -cellSize * i);

                    // Skip the last row and column for triangles
                    if (i < rows - 1 && j < columns - 1) {
                        int topLeft = vertexIndex;
                        int topRight = topLeft + 1;
                        int bottomLeft = topLeft + columns;
                        int bottomRight = bottomLeft + 1;

                        // left triangle
                        triangles[triangleIndex++] = topLeft;
                        triangles[triangleIndex++] = bottomRight;
                        triangles[triangleIndex++] = bottomLeft;

                        // right triangle
                        triangles[triangleIndex++] = topLeft;
                        triangles[triangleIndex++] = topRight;
                        triangles[triangleIndex++] = bottomRight;
                    }
                }
            }

            meshOut.vertices = vertices;
            meshOut.triangles = triangles;
            return meshOut;
        }


        /// Searches for the water surface using the water simulation data.
        private void ExecuteWaterSimulationSearchJob(WaterSimSearchData simData, Vector3[] vertices) {
            using var marker = CraneProfiler.WaterQuery.Auto();
            // Prepare the first band
            WaterSimulationSearchJob searchJob = new() {
                // Assign the simulation data
                simSearchData = simData,
                // Fill the input data
                targetPositionWSBuffer = targetPositionBuffer,
                startPositionWSBuffer = targetPositionBuffer,
                maxIterations = 8,
                error = 0.01f,
                includeDeformation = true,
                excludeSimulation = false,

                errorBuffer = errorBuffer,
                candidateLocationWSBuffer = candidatePositionWorldSpaceBuffer,
                projectedPositionWSBuffer = projectedPositionWorldSpaceBuffer,
                directionBuffer = directionBuffer,
                stepCountBuffer = stepCountBuffer,
                normalWSBuffer = normalWSBuffer
            };

            // Schedule one search per work-stealing unit. A matched batch-size-eight experiment
            // did not improve the 121-point production WamV patch.
            JobHandle handle = searchJob.Schedule(vertices.Length, 1);
            handle.Complete();
        }


        /// Move the patch to the boat transforms
        private void SetGridOrigin(Transform transform) {
            float x = -sideLength / 2 + transform.position.x;
            float z = sideLength / 2 + transform.position.z;
            gridOrigin = new Vector3(x, 0, z);
        }


        // Called from Submerged.cs
        /// Returns the height of the water surface at the specified point in world space.
        /// By using the patch grid, the water surface height is queried at the specified point.
        /// Run over each point in physics mesh. Called from Submerged.cs/GetSubmergedTriangles()
        public float GetPatchRelativeHeight(Vector3 point) {
            (Vector3, Vector3, Vector3) patchVertices = GetPatchTriangleVerticesWorld(point);
            return GetHeightAboveTriangle(point, patchVertices);
        }


        /// For the points of the submerged mesh, returns the height above the water surface.
        private float GetHeightAboveTriangle(Vector3 point, (Vector3, Vector3, Vector3) triangle) {
            Vector3 edgeAtoB = triangle.Item2 - triangle.Item1;
            Vector3 edgeAtoC = triangle.Item3 - triangle.Item1;
            Vector3 triangleNormal = Vector3.Cross(edgeAtoB, edgeAtoC);
            // The plane equation
            float distance = Vector3.Dot(triangleNormal, triangle.Item1);
            //if (abc.y == 0.0f) - Old line
            if (Math.Abs(triangleNormal.y) < 0.00001f)
                Console.WriteLine("Division by zero when calculating height of point above triangle plane!");

            float heightAboveTriangle = (distance - triangleNormal.x * point.x - triangleNormal.z * point.z);
            heightAboveTriangle /= triangleNormal.y;
            heightAboveTriangle = point.y - heightAboveTriangle;
            return heightAboveTriangle;
            //return (point.y - (distance - triangleNormal.x * point.x - triangleNormal.z * point.z) / triangleNormal.y); - Old Line
        }


        /// Returns the world space vertices of the triangle in which the point lies.
        private (Vector3, Vector3, Vector3) GetPatchTriangleVerticesWorld(Vector3 point) {
            (int rowCell, int columnCell) = PointToCell(point);
            float xInCell = (point.x - gridOrigin.x) - cellSize * columnCell;
            float zInCell = (point.z - gridOrigin.z) - (cellSize * (-rowCell));
            bool left = (xInCell >= -zInCell);
            return GetPatchTriangleVertices(rowCell, columnCell, left);
        }


        /// Returns the row and column indices of the cell in which the point lies.
        private (int, int) PointToCell(Vector3 point) {
            Vector3 adjustedPoint = point - gridOrigin;
            int rowIndex = Mathf.FloorToInt(-adjustedPoint.z / cellSize);
            int columnIndex = Mathf.FloorToInt(adjustedPoint.x / cellSize);
            return (rowIndex, columnIndex);
        }


        /// Returns the vertices of the triangle in the patch grid at the specified row and column indices.
        /// Depending on the value of the left parameter, the left or right triangle is returned.
        private (Vector3, Vector3, Vector3) GetPatchTriangleVertices(int rowIndex, int columnIndex, bool left) {
            int numberOfVertices = gridFidelity + 1;
            Vector3 topLeftVertex = patchVertices[rowIndex * numberOfVertices + columnIndex];
            Vector3 bottomRightVertex = patchVertices[(rowIndex + 1) * numberOfVertices + (columnIndex + 1)];

            if (left) {
                Vector3 bottomLeftVertex = patchVertices[(rowIndex + 1) * numberOfVertices + columnIndex];
                return (topLeftVertex, bottomLeftVertex, bottomRightVertex); // Left triangle
            }
            else {
                Vector3 topRightVertex = patchVertices[rowIndex * numberOfVertices + (columnIndex + 1)];
                return (topLeftVertex, bottomRightVertex, topRightVertex); // Right triangle
            }
        }


        public void Dispose() {
            DisposeRoutine();
        }


        /// Dispose of the buffers.
        private void DisposeRoutine() {
            projectedPositionWorldSpaceBuffer.Dispose();
            candidatePositionWorldSpaceBuffer.Dispose();
            targetPositionBuffer.Dispose();
            directionBuffer.Dispose();
            stepCountBuffer.Dispose();
            errorBuffer.Dispose();
            normalWSBuffer.Dispose();
        }
    }
}

using UnityEngine;
using System;
using Sim.Utils;

// TODO: Investigate if transforms could be optimized by using a single transform for all submerged objects

namespace Sim.Physics.Processing {
    public static class SubmersionUtils {
        public static float[] CalculateTriangleAreas(Data data) {
            int triangleCount = data.maxTriangleIndex / 3;
            float[] triangleAreas = data.triangleAreas;

            for (int i = 0; i < data.maxTriangleIndex; i += 3) {
                Vector3 v1 = data.vertices[data.triangles[i + 1]] - data.vertices[data.triangles[i]];
                Vector3 v2 = data.vertices[data.triangles[i + 2]] - data.vertices[data.triangles[i]];
                float area = 0.5f * Vector3.Cross(v1, v2).magnitude;
                triangleAreas[i / 3] = area;
            }
            return triangleAreas;
        }


        public static void DrawPatch(Patch patch) {
            int[] triangles = patch.baseGridMesh.triangles;
            Vector3[] vertices = patch.patchVertices;
            for (var i = 0; i < triangles.Length; i += 3) {
                Vector3[] tri = new Vector3[] { vertices[triangles[i]], vertices[triangles[i + 1]], vertices[triangles[i + 2]] };
                CommonUtils.DebugDrawTriangle(tri, Color.red);
            }
        }
    }

    // Class holding the vertices, triangles and normals of the submerged mesh, and more.
    [Serializable]
    public class Data {
        public Vector3[] vertices;
        public int[] triangles;
        public Vector3[] normals;
        public Transform transform;

        public Vector3[] faceCentersWorld;
        public float[] faceCenterHeightsAboveWater;
        public float[] triangleAreas;
        public Vector3 centroid;
        public float volume;
        public int maxTriangleIndex;

        public Data(int maxNumTriangles) {
            vertices = new Vector3[maxNumTriangles];
            triangles = new int[maxNumTriangles];
            normals = new Vector3[maxNumTriangles / 3];
            faceCentersWorld = new Vector3[maxNumTriangles / 3];
            faceCenterHeightsAboveWater = new float[maxNumTriangles / 3];
            triangleAreas = new float[maxNumTriangles / 3];
            centroid = new Vector3();
            volume = new float();
            maxTriangleIndex = 0;
        }
    }

    [Serializable]
    public class Submerged {
        // OK Public

        public Data data;

        // OK Private
        public Mesh hullMesh;
        // caching input mesh data (these shouldnt change at runtime)
        private Vector3[] hullMeshVertices, hullMeshNormals;
        private int[] hullMeshTriangles;

        private Vector3[] verticesLocal = new Vector3[3];
        private Vector3[] verticesWorld = new Vector3[3];
        private Vector3[] normalsLocal = new Vector3[3];
        private float[] vertexHeights = new float[3];


        // Only submergedVolume uses these

        // Called from Submersion.cs
        // Populates global variables with the submerged mesh and its properties
        public Submerged(Mesh simplifiedHullMesh, bool debug = false) {
            hullMesh = simplifiedHullMesh;
            hullMeshVertices = simplifiedHullMesh.vertices;
            hullMeshNormals = simplifiedHullMesh.normals;
            hullMeshTriangles = simplifiedHullMesh.triangles;

            data = new Data(simplifiedHullMesh.triangles.Length * 2);
        }


        public void Update(Patch patch, Transform submersionTransform) {
            data.maxTriangleIndex = 0;
            data.transform = submersionTransform;

            ProduceSubmergedTriangles(data, patch, hullMeshVertices, hullMeshTriangles, hullMeshNormals);

            // TODO: Consider setting globals in function, no return
            data.triangleAreas = GetTriangleAreas(data);
            data.faceCenterHeightsAboveWater = GetTriangleCenterHeights(data, patch);
            (data.volume, data.centroid) = GetSubmergedVolume(data, data.faceCenterHeightsAboveWater);
            GetFaceCenters(data);
        }


        // Called in Update
        // Returns the arrays of vertices, triangles and normals of the submerged mesh.
        // It also splits the triangles depending on how many vertices are submerged.
        public void ProduceSubmergedTriangles
            (Data data, Patch patch, Vector3[] bodyVertices, int[] bodyTriangles, Vector3[] bodyVertNormals) {
            // Loop through input triangles
            for (int i = 0; i < bodyTriangles.Length - 2; i += 3) {

                int submergedCount = 0;

                // Get the local and world positions of the current triangle,
                // compute depth, track number of submerged vertices in triangle
                for (int j = 0; j < 3; j++) {
                    verticesLocal[j] = bodyVertices[bodyTriangles[i + j]];
                    normalsLocal[j] = bodyVertNormals[bodyTriangles[i + j]];
                    verticesWorld[j] = data.transform.TransformPoint(verticesLocal[j]);
                    float height = patch.GetPatchRelativeHeight(verticesWorld[j]);
                    vertexHeights[j] = height;
                    if (height < 0) submergedCount++; // depth > 0 == submerged point

                }

                Vector3 triangleNormal = (normalsLocal[0] + normalsLocal[1] + normalsLocal[2]).normalized;

                // How many vertices are underwater?
                // Split them accordingly
                switch (submergedCount) {
                    case 0: {
                            break;
                        }
                    case 1: {
                            (Vector3[] localVerticesSorted, float[] sortedHeights) = SortVerticesAgainstFloats(verticesLocal, vertexHeights);
                            Vector3 highestMinusLowestPoint = localVerticesSorted[2] - localVerticesSorted[0];
                            Vector3 highestMinusMiddlePoint = localVerticesSorted[1] - localVerticesSorted[0];

                            float heightRatioLowToMid = -sortedHeights[0] / (sortedHeights[1] - sortedHeights[0]);
                            float heightRatioLowToHigh = -sortedHeights[0] / (sortedHeights[2] - sortedHeights[0]);

                            Vector3 intersectPointLowToHigh = heightRatioLowToHigh * highestMinusLowestPoint;
                            Vector3 intersectPointLowToMid = heightRatioLowToMid * highestMinusMiddlePoint;

                            Vector3 newEdgeLowToHigh = localVerticesSorted[0] + intersectPointLowToHigh;
                            Vector3 newEdgeLowToMid = localVerticesSorted[0] + intersectPointLowToMid;

                            AppendTriangle(data, localVerticesSorted[0], newEdgeLowToHigh, newEdgeLowToMid, triangleNormal);
                            break;
                        }
                    case 2: {
                            (Vector3[] localVerticesSorted, float[] sortedHeights) = SortVerticesAgainstFloats(verticesLocal, vertexHeights);

                            Vector3 highestMinusLowestPoint = localVerticesSorted[2] - localVerticesSorted[0];
                            Vector3 highestMinusMiddlePoint = localVerticesSorted[2] - localVerticesSorted[1];

                            float heightRatioHighToMid = -sortedHeights[1] / (sortedHeights[2] - sortedHeights[1]);
                            float heightRatioHighToLow = -sortedHeights[0] / (sortedHeights[2] - sortedHeights[0]);

                            Vector3 intersectPointHighToLow = heightRatioHighToLow * highestMinusLowestPoint;
                            Vector3 intersectPointHighToMid = heightRatioHighToMid * highestMinusMiddlePoint;

                            Vector3 newEdgeHighToLow = localVerticesSorted[0] + intersectPointHighToLow;
                            Vector3 newEdgeHighToMid = localVerticesSorted[1] + intersectPointHighToMid;

                            AppendTriangle(data, localVerticesSorted[1], newEdgeHighToMid, localVerticesSorted[0], triangleNormal);
                            AppendTriangle(data, localVerticesSorted[0], newEdgeHighToMid, newEdgeHighToLow, triangleNormal);
                            break;
                        }
                    case 3: {
                            AppendTriangle(data, verticesLocal[0], verticesLocal[1], verticesLocal[2], triangleNormal);
                            break;
                        }
                }
            }
        }


        // Returns the areas of the triangles in the submerged mesh.
        // Takes in the vertices of the submerged mesh.
        public float[] GetTriangleAreas(Data data) {
            Vector3[] vertices = data.vertices;
            float[] areas = data.triangleAreas;
            for (int i = 0; i < data.maxTriangleIndex - 2; i += 3) {
                Vector3 normal = CommonUtils.GetFaceNormal(vertices[i], vertices[i + 1], vertices[i + 2]);
                areas[i / 3] = normal.magnitude;
            }
            return areas;
        }


        // Called in GetSubmergedTriangles
        // Updates the vertices, triangles and normals of the submerged mesh.
        public void AppendTriangle(Data data, Vector3 v1, Vector3 v2, Vector3 v3, Vector3 triNormal) {
            int currentIndex = data.maxTriangleIndex;
            data.triangles[currentIndex] = currentIndex;
            data.triangles[currentIndex + 1] = currentIndex + 1;
            data.triangles[currentIndex + 2] = currentIndex + 2;

            data.vertices[currentIndex] = v1;
            data.vertices[currentIndex + 1] = v2;
            data.vertices[currentIndex + 2] = v3;
            data.normals[currentIndex / 3] = triNormal;
            data.maxTriangleIndex = currentIndex + 3;
        }


        // Calculates the difference of volume between the submerged part of hull and any eventual
        // water above it. Also calculates the center of volume of this submerged part of the hull.
        public (float vol, Vector3 volCenter) GetSubmergedVolume(Data data, float[] heights) {
            Transform submersionTransform = data.transform;
            Vector3[] vertices = data.vertices;
            int[] triangles = data.triangles;
            Vector3[] normals = data.normals;

            float totalVolumeDown = 0f;
            float totalVolumeUp = 0f;
            Vector3 sumVolumeCenterDown = Vector3.zero;
            Vector3 sumVolumeCenterUp = Vector3.zero;

            Vector3[] pointsWorldSpace = new Vector3[3];

            for (int i = 0; i < this.data.maxTriangleIndex; i += 3) {
                float depth = -heights[i / 3];
                pointsWorldSpace[0] = submersionTransform.TransformPoint(vertices[triangles[i]]);
                pointsWorldSpace[1] = submersionTransform.TransformPoint(vertices[triangles[i + 1]]);
                pointsWorldSpace[2] = submersionTransform.TransformPoint(vertices[triangles[i + 2]]);


                // Triangle edges projected on horizontal plane (?)
                Vector3 edgeAtoB = pointsWorldSpace[1] - pointsWorldSpace[0]; edgeAtoB.y = 0f;
                Vector3 edgeAtoC = pointsWorldSpace[2] - pointsWorldSpace[0]; edgeAtoC.y = 0f;

                // Get the area of the triangle in the horizontal plane
                float projectedArea = 0.5f * Vector3.Cross(edgeAtoB, edgeAtoC).magnitude;
                float volume = projectedArea * depth;

                Vector3 centroid = (pointsWorldSpace[0] + pointsWorldSpace[1] + pointsWorldSpace[2]) / 3.0f;//+new Vector3(0f, depth*0.5f, 0)
                centroid.y += depth * 0.5f;

                // Determine if face is pointing up (negative contribution) or down (positive contribution) //TODO: MOVE DOWN
                bool trianglePointingDown = submersionTransform.TransformDirection(normals[i / 3]).y < 0;
                if (trianglePointingDown) {
                    sumVolumeCenterDown += centroid * volume;
                    totalVolumeDown += volume;
                }
                else {
                    sumVolumeCenterUp += centroid * volume;
                    totalVolumeUp += volume;
                }
            }

            float totalVolume = totalVolumeDown - totalVolumeUp;

            if (Math.Abs(totalVolume) < 0.00001f) return (0f, Vector3.zero); //Changed these to a comparison with a small number

            Vector3 centroidUp = (Math.Abs(totalVolumeUp) < 0.00001f) ? Vector3.zero : sumVolumeCenterUp / totalVolumeUp;
            Vector3 centroidDown = (Math.Abs(totalVolumeDown) < 0.00001f) ? Vector3.zero : sumVolumeCenterDown / totalVolumeDown;

            Vector3 center = (centroidDown * totalVolumeDown - centroidUp * totalVolumeUp) / (totalVolume);
            return (totalVolume, center);
        }


        // Queries the patch for the height of the center of each triangle in the submerged mesh.
        // Returns a float array of the heights.
        public float[] GetTriangleCenterHeights(Data data, Patch patch) {
            Transform transform = data.transform;
            Vector3[] vertices = data.vertices;
            int[] triangles = data.triangles;
            float[] heights = this.data.faceCenterHeightsAboveWater;

            for (int i = 0; i < data.maxTriangleIndex - 2; i += 3) {
                Vector3 centerVert = (vertices[triangles[i]] + vertices[triangles[i + 1]] + vertices[triangles[i + 2]]) / 3.0f;
                heights[i / 3] = patch.GetPatchRelativeHeight(transform.TransformPoint(centerVert));
            }
            return heights;
        }


        // Calculates the center of each triangle in the submerged mesh.
        public Vector3[] GetFaceCenters(Data data) {
            Transform transform = data.transform;
            Vector3[] vertices = data.vertices;
            int[] triangles = data.triangles;
            Vector3[] centers = this.data.faceCentersWorld;

            for (int i = 0; i < data.maxTriangleIndex - 2; i += 3) {
                Vector3 centerLocal = (vertices[triangles[i]] + vertices[triangles[i + 1]] + vertices[triangles[i + 2]]) / 3.0f;
                centers[i / 3] = transform.TransformPoint(centerLocal);
            }
            return centers;
        }


        // Calculates the resistance coefficient of the submerged hull.
        public float GetResistanceCoefficient(float speed, float hullZmin, float hullZmax, Data data) {
            float submergedArea = CalculateMeshArea(data);
            float Rn = CalculateReynoldsNumber(speed, Math.Abs(hullZmax - hullZmin));

            float onePlusK = 0;
            for (int i = 0; i < data.maxTriangleIndex - 2; i += 3) {
                Vector3 v0 = data.vertices[data.triangles[i]];
                Vector3 v1 = data.vertices[data.triangles[i + 1]];
                Vector3 v2 = data.vertices[data.triangles[i + 2]];
                float Si = (0.5f) * Vector3.Cross((v1 - v0), (v2 - v0)).magnitude;
                float Ki = GetTriangleK((v0.z + v1.z + v2.z) / 3.0f, hullZmin, hullZmax);
                onePlusK += (1 + Ki) * Si;
            }
            onePlusK = Mathf.Clamp(onePlusK / submergedArea, 1.22f, 1.65f);
            float Cf = 0.075f / ((Mathf.Log10(Rn) - 2.0f) * (Mathf.Log10(Rn) - 2.0f));
            float Cfr = onePlusK * Cf;
            return Cfr;
        }


        public float CalculateMeshArea(Data data) {
            float totalArea = 0.0f;
            for (int i = 0; i < data.maxTriangleIndex - 2; i += 3) {
                Vector3 v1 = data.vertices[data.triangles[i + 1]] - data.vertices[data.triangles[i]];
                Vector3 v2 = data.vertices[data.triangles[i + 2]] - data.vertices[data.triangles[i]];
                Vector3 cross = Vector3.Cross(v1, v2);
                totalArea += 0.5f * cross.magnitude;
            }
            return totalArea;
        }


        // Used in GetResistanceCoefficient
        private float CalculateReynoldsNumber(float velocity, float L, float viscosity = Constants.waterViscosity) {
            return (velocity * L) / viscosity;
        }


        // Used in GetResistanceCoefficient
        private float GetTriangleK(float z, float hullZmin, float hullZmax) {
            float f = (-3.0f / (hullZmax - hullZmin)) * z + 3.0f * hullZmax / (hullZmax - hullZmin) - 1.0f;
            return f;
        }

        // Sorts the vertices of a triangle by their heights.
        // Indexed from 0 to 2, low to high.
        // Called in GetSubmergedTriangles.
        private static (Vector3[], float[]) SortVerticesAgainstFloats(Vector3[] vertices, float[] heights) {
            if (heights[0] > heights[1]) {
                Swap(ref heights[0], ref heights[1]);
                Swap(ref vertices[0], ref vertices[1]);
            }

            if (heights[1] > heights[2]) {
                Swap(ref heights[1], ref heights[2]);
                Swap(ref vertices[1], ref vertices[2]);
            }

            if (heights[0] > heights[1]) {
                Swap(ref heights[0], ref heights[1]);
                Swap(ref vertices[0], ref vertices[1]);
            }

            return (vertices, heights);
        }


        private static void Swap<T>(ref T a, ref T b) {
            T temp = a;
            a = b;
            b = temp;
        }
    }
}

