using System;
using UnityEngine;

namespace Sim.Utils {
    [Serializable]
    public class Pid {
        public float Kp;
        public float Ki;
        public float Kd;
        public float bound;
        private float integral, prev;

        public Pid(float Kp, float Ki, float Kd) {
            this.Kp = Kp;
            this.Ki = Ki;
            this.Kd = Kd;
        }

        public float Run(float error, float dt) {
            float change = (error - prev) / dt;
            prev = error;
            integral += error * dt;
            integral = Mathf.Clamp(integral, -bound, bound);
            return Kp * error + Ki * integral + Kd * change;
        }

        public Pid Clone() =>
            new(Kp, Ki, Kd);

        public void Reset() {
            integral = 0;
            prev = 0;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Globalization;

namespace Sim.Utils.Performance {
    public enum CraneActionPolicy {
        LatestValid,
        BoundedLag
    }

    public enum CraneActionRejection {
        None,
        CrossEpisode,
        DuplicateOrOutOfOrder,
        Stale
    }

    public readonly struct CraneActionReceipt {
        public readonly string Source;
        public readonly long EpisodeId;
        public readonly long Sequence;
        public readonly long SourceObservationTick;
        public readonly long ReceiveTick;

        internal CraneActionReceipt(string source, long episodeId, long sequence,
            long sourceObservationTick, long receiveTick) {
            Source = source;
            EpisodeId = episodeId;
            Sequence = sequence;
            SourceObservationTick = sourceObservationTick;
            ReceiveTick = receiveTick;
        }
    }

    public readonly struct CraneActionPayload {
        public readonly string Encoding;
        public readonly byte[] Data;

        public CraneActionPayload(string encoding, byte[] data) {
            Encoding = encoding ?? string.Empty;
            Data = data ?? Array.Empty<byte>();
        }
    }

    public readonly struct CraneAcceptedAction {
        public readonly string Source;
        public readonly long EpisodeId;
        public readonly long Sequence;
        public readonly long SourceObservationTick;
        public readonly long ReceiveTick;
        public readonly long ApplicationTick;
        public readonly CraneActionPayload Payload;

        internal CraneAcceptedAction(in CraneActionReceipt receipt, long applicationTick,
            in CraneActionPayload payload) {
            Source = receipt.Source;
            EpisodeId = receipt.EpisodeId;
            Sequence = receipt.Sequence;
            SourceObservationTick = receipt.SourceObservationTick;
            ReceiveTick = receipt.ReceiveTick;
            ApplicationTick = applicationTick;
            Payload = payload;
        }
    }

    public static class CraneActionPayloadEncoding {
        public static CraneActionPayload Float32(float value) {
            int bits = BitConverter.SingleToInt32Bits(value);
            return new CraneActionPayload("float32-le", new[] {
                (byte)bits, (byte)(bits >> 8), (byte)(bits >> 16), (byte)(bits >> 24)
            });
        }

        public static CraneActionPayload Int32(int value) =>
            new("int32-le", new[] {
                (byte)value, (byte)(value >> 8), (byte)(value >> 16), (byte)(value >> 24)
            });

        public static CraneActionPayload UInt16Array(ushort[] values) {
            byte[] bytes = new byte[values.Length * sizeof(ushort)];
            for (int i = 0; i < values.Length; i++) {
                bytes[i * 2] = (byte)values[i];
                bytes[i * 2 + 1] = (byte)(values[i] >> 8);
            }
            return new CraneActionPayload("uint16-le[]", bytes);
        }

        public static CraneActionPayload Float32Array(float[] values) {
            byte[] bytes = new byte[values.Length * sizeof(float)];
            for (int i = 0; i < values.Length; i++) {
                int bits = BitConverter.SingleToInt32Bits(values[i]);
                int offset = i * sizeof(float);
                bytes[offset] = (byte)bits;
                bytes[offset + 1] = (byte)(bits >> 8);
                bytes[offset + 2] = (byte)(bits >> 16);
                bytes[offset + 3] = (byte)(bits >> 24);
            }
            return new CraneActionPayload("float32-le[]", bytes);
        }
    }

    /// <summary>
    /// Single-slot, latest-value mailbox for transport callbacks. Receive may run on a
    /// background thread; TryApply is called by the owning component from FixedUpdate.
    /// Replacing an unconsumed payload is intentional for latest-command control streams.
    /// </summary>
    public sealed class CraneQueuedAction<T> {
        private readonly object queueLock = new();
        private readonly long auditMailbox = CraneActionTimingAudit.NewMailbox();
        private readonly Func<T, CraneActionPayload> payloadEncoder;
        private T pendingPayload;
        private CraneActionReceipt pendingReceipt;
        private bool hasPending;

        public CraneQueuedAction(Func<T, CraneActionPayload> payloadEncoder = null) {
            this.payloadEncoder = payloadEncoder;
        }

        public void Receive(T payload, string source, long sequence,
            long sourceObservationTick = -1) {
            CraneActionReceipt receipt = CraneActionGate.Receive(source, sequence,
                sourceObservationTick);
            lock (queueLock) {
                if (hasPending) CraneActionTimingAudit.Record("mailbox_overwrite", pendingReceipt, auditMailbox, hadPending: true);
                CraneActionTimingAudit.Record("mailbox_enqueue", receipt, auditMailbox, hadPending: hasPending);
                pendingPayload = payload;
                pendingReceipt = receipt;
                hasPending = true;
            }
        }

        public bool TryApply(Action<T> apply, out CraneActionRejection rejection) {
            T payload;
            CraneActionReceipt receipt;
            lock (queueLock) {
                if (!hasPending) {
                    rejection = CraneActionRejection.None;
                    return false;
                }
                payload = pendingPayload;
                receipt = pendingReceipt;
                CraneActionTimingAudit.Record("mailbox_consume", receipt, auditMailbox, hadPending: true);
                pendingPayload = default;
                hasPending = false;
            }

            if (!CraneActionGate.TryApply(receipt, out rejection)) return false;
            apply(payload);
            if (payloadEncoder != null && CraneActionGate.HasAcceptedActionObservers)
                CraneActionGate.ReportAcceptedPayload(receipt, payloadEncoder(payload));
            return true;
        }

        public void Clear(string reason = "unspecified") {
            lock (queueLock) {
                CraneActionTimingAudit.Record("mailbox_clear", pendingReceipt, auditMailbox, reason, hasPending);
                pendingPayload = default;
                pendingReceipt = default;
                hasPending = false;
            }
        }
    }

    /// <summary>
    /// Thread-safe action provenance and acceptance module. Transport adapters receive an
    /// immutable receipt, then cross this seam once on the Unity fixed-update thread before
    /// mutating actuators.
    /// </summary>
    public static class CraneActionGate {
        private readonly struct AppliedSequence {
            public readonly long EpisodeId;
            public readonly long Sequence;
            public AppliedSequence(long episodeId, long sequence) {
                EpisodeId = episodeId;
                Sequence = sequence;
            }
        }

        private static readonly object s_Lock = new();
        private static readonly Dictionary<string, AppliedSequence> s_LastApplied = new();
        private static Action<CraneAcceptedAction> s_AcceptedActionObservers;
        private static CraneActionPolicy s_Policy;
        private static long s_MaxLagTicks;

        static CraneActionGate() {
            string[] args = Environment.GetCommandLineArgs();
            string policy = ReadArgument(args, "--crane-action-policy") ?? "latest";
            s_Policy = policy.Equals("bounded", StringComparison.OrdinalIgnoreCase) ?
                CraneActionPolicy.BoundedLag : CraneActionPolicy.LatestValid;
            s_MaxLagTicks = Math.Max(0, ReadLong(args, "--crane-max-action-lag-ticks", 5));
        }

        public static CraneActionPolicy Policy {
            get { lock (s_Lock) return s_Policy; }
        }
        public static long MaximumLagTicks {
            get { lock (s_Lock) return s_MaxLagTicks; }
        }
        internal static bool HasAcceptedActionObservers {
            get { lock (s_Lock) return s_AcceptedActionObservers != null; }
        }

        public static void SubscribeAcceptedActions(Action<CraneAcceptedAction> observer) {
            if (observer == null) throw new ArgumentNullException(nameof(observer));
            lock (s_Lock) s_AcceptedActionObservers += observer;
        }

        public static void UnsubscribeAcceptedActions(Action<CraneAcceptedAction> observer) {
            if (observer == null) return;
            lock (s_Lock) s_AcceptedActionObservers -= observer;
        }

        public static CraneActionReceipt Receive(string source, long sequence,
            long sourceObservationTick = -1) {
            var receipt = new CraneActionReceipt(source ?? "unknown",
                CraneRuntimeMetrics.EpisodeId, sequence, sourceObservationTick,
                CraneRuntimeMetrics.SimulationTick);
            CraneRuntimeMetrics.ReportActionReceived(receipt.ReceiveTick,
                sourceObservationTick < 0);
            CraneActionTimingAudit.Record("receive", receipt);
            return receipt;
        }

        public static bool TryApply(in CraneActionReceipt receipt,
            out CraneActionRejection rejection) {
            long episodeId = CraneRuntimeMetrics.EpisodeId;
            long applicationTick = CraneRuntimeMetrics.SimulationTick;
            lock (s_Lock) {
                if (receipt.EpisodeId != episodeId) {
                    rejection = CraneActionRejection.CrossEpisode;
                    if (CraneActionTimingAudit.Enabled) CraneActionTimingAudit.Record("gate_decision", receipt, reason: rejection.ToString(), applicationTick: applicationTick, policy: s_Policy, maximumLagTicks: s_MaxLagTicks, decisionEpisode: episodeId);
                    CraneRuntimeMetrics.ReportRejectedAction(rejection);
                    return false;
                }

                if (s_LastApplied.TryGetValue(receipt.Source, out AppliedSequence last) &&
                    last.EpisodeId == episodeId && receipt.Sequence <= last.Sequence) {
                    rejection = CraneActionRejection.DuplicateOrOutOfOrder;
                    if (CraneActionTimingAudit.Enabled) CraneActionTimingAudit.Record("gate_decision", receipt, reason: rejection.ToString(), applicationTick: applicationTick, policy: s_Policy, maximumLagTicks: s_MaxLagTicks, decisionEpisode: episodeId);
                    CraneRuntimeMetrics.ReportRejectedAction(rejection);
                    return false;
                }

                long provenanceTick = receipt.SourceObservationTick >= 0 ?
                    receipt.SourceObservationTick : receipt.ReceiveTick;
                if (s_Policy == CraneActionPolicy.BoundedLag &&
                    applicationTick - provenanceTick > s_MaxLagTicks) {
                    rejection = CraneActionRejection.Stale;
                    if (CraneActionTimingAudit.Enabled) CraneActionTimingAudit.Record("gate_decision", receipt, reason: rejection.ToString(), applicationTick: applicationTick, policy: s_Policy, maximumLagTicks: s_MaxLagTicks, decisionEpisode: episodeId);
                    CraneRuntimeMetrics.ReportRejectedAction(rejection);
                    return false;
                }

                s_LastApplied[receipt.Source] = new AppliedSequence(episodeId, receipt.Sequence);
                CraneActionTimingAudit.Record("gate_decision", receipt, reason: "None", applicationTick: applicationTick, policy: s_Policy, maximumLagTicks: s_MaxLagTicks, decisionEpisode: episodeId);
            }

            rejection = CraneActionRejection.None;
            CraneRuntimeMetrics.ReportAction(receipt.SourceObservationTick, receipt.ReceiveTick,
                applicationTick, receipt.Sequence);
            return true;
        }

        public static void Configure(CraneActionPolicy policy, long maximumLagTicks) {
            lock (s_Lock) {
                s_Policy = policy;
                s_MaxLagTicks = Math.Max(0, maximumLagTicks);
                s_LastApplied.Clear();
                CraneActionTimingAudit.Record("gate_configure", default, policy: s_Policy, maximumLagTicks: s_MaxLagTicks, decisionEpisode: CraneRuntimeMetrics.EpisodeId);
            }
        }

        public static void BeginEpisode() {
            lock (s_Lock) {
                s_LastApplied.Clear();
                CraneActionTimingAudit.Record("gate_episode_reset", default, policy: s_Policy, maximumLagTicks: s_MaxLagTicks, decisionEpisode: CraneRuntimeMetrics.EpisodeId);
            }
        }

        internal static void ReportAcceptedPayload(in CraneActionReceipt receipt,
            in CraneActionPayload payload) {
            Action<CraneAcceptedAction> observers;
            lock (s_Lock) observers = s_AcceptedActionObservers;
            if (observers == null) return;
            var accepted = new CraneAcceptedAction(receipt,
                CraneRuntimeMetrics.ActionApplicationTick, payload);
            observers.Invoke(accepted);
        }

        private static string ReadArgument(string[] args, string key) {
            int index = Array.IndexOf(args, key);
            return index >= 0 && index + 1 < args.Length ? args[index + 1] : null;
        }

        private static long ReadLong(string[] args, string key, long fallback) =>
            long.TryParse(ReadArgument(args, key), NumberStyles.Integer,
                CultureInfo.InvariantCulture, out long value) ? value : fallback;
    }
}

using System;
using System.Collections.Concurrent;
using System.Diagnostics;
using System.IO;
using System.Threading;
using UnityEngine;

namespace Sim.Utils.Performance {
    [Serializable] public sealed class CraneActionTimingEvent {
        public string kind, source, reason, policy, payloadEncoding;
        public byte[] payload;
        public long ordinal, monotonic, episode, sequence, sourceTick, receiveTick,
            applicationTick, decisionEpisode, maximumLagTicks, mailbox, rawSeconds, rawNanoseconds;
        public long callbackCompletionTick = -1, snapshotTick = -1;
        public long acceptedActions = -1, rejectedActions = -1, staleActions = -1,
            crossEpisodeActions = -1, duplicateActions = -1, unknownSourceActions = -1;
        public bool hadPending;
    }

    // All producer paths buffer only. Serialization and IO run in the owner drain.
    // A closed session rejects late callbacks; StopRecording unsubscribes before final drain.
    public static class CraneActionTimingAudit {
        public const int DefaultCapacity = 100000;
        public const int DefaultMaximumPayloadBytes = 65536;
        public const int DefaultPayloadByteCapacity = 16777216;
        private sealed class Buffer {
            public readonly object sync = new();
            public readonly ConcurrentQueue<CraneActionTimingEvent> queue = new();
            public readonly int capacity, maximumPayloadBytes, payloadByteCapacity;
            public int count, payloadBytes, failed, closed, subscribed;
            public long dropped, ordinal, written, enqueued, attempts;
            public Action<CraneAcceptedAction> observer;
            public Buffer(int capacity, int maximumPayloadBytes, int payloadByteCapacity) {
                this.capacity = capacity; this.maximumPayloadBytes = maximumPayloadBytes;
                this.payloadByteCapacity = payloadByteCapacity;
            }
        }
        private static readonly object lifecycle = new();
        private static Buffer active;
        private static long mailboxSequence;
        public static long NewMailbox() => Interlocked.Increment(ref mailboxSequence);
        public static bool Enabled => Volatile.Read(ref active) is Buffer b && Volatile.Read(ref b.closed) == 0;
        public static long Dropped => Volatile.Read(ref active) is Buffer b ? Interlocked.Read(ref b.dropped) : 0;
        public static int Buffered => Volatile.Read(ref active) is Buffer b ? Volatile.Read(ref b.count) : 0;
        public static int BufferedPayloadBytes => Volatile.Read(ref active) is Buffer b ? Volatile.Read(ref b.payloadBytes) : 0;
        public static long Written => Volatile.Read(ref active) is Buffer b ? Interlocked.Read(ref b.written) : 0;
        public static long Enqueued => Volatile.Read(ref active) is Buffer b ? Interlocked.Read(ref b.enqueued) : 0;
        public static long EventAttempts => Volatile.Read(ref active) is Buffer b ? Interlocked.Read(ref b.attempts) : 0;
        public static bool WriterFailed => Volatile.Read(ref active) is Buffer b && Volatile.Read(ref b.failed) != 0;
        public static bool AcceptedObserverSubscribed => Volatile.Read(ref active) is Buffer b && Volatile.Read(ref b.subscribed) != 0;
        public static void StartBuffer(int capacity = DefaultCapacity,
            int maximumPayloadBytes = DefaultMaximumPayloadBytes,
            int payloadByteCapacity = DefaultPayloadByteCapacity) {
            if (capacity < 1 || maximumPayloadBytes < 0 || payloadByteCapacity < 0)
                throw new ArgumentOutOfRangeException(nameof(capacity));
            lock (lifecycle) {
                if (active != null) throw new InvalidOperationException("End and drain the existing audit session before replacing it");
                var b = new Buffer(capacity, maximumPayloadBytes, payloadByteCapacity);
                b.observer = action => RecordAccepted(b, action);
                Volatile.Write(ref active, b);
                CraneActionGate.SubscribeAcceptedActions(b.observer);
                Volatile.Write(ref b.subscribed, 1);
            }
        }
        public static void StopRecording() {
            lock (lifecycle) {
                Buffer b = Volatile.Read(ref active);
                if (b == null) return;
                // No gate lock is held while acquiring the buffer lock or vice versa.
                lock (b.sync) b.closed = 1;
                if (Interlocked.Exchange(ref b.subscribed, 0) != 0)
                    CraneActionGate.UnsubscribeAcceptedActions(b.observer);
            }
        }
        public static void Disable() {
            lock (lifecycle) {
                StopRecording();
                Volatile.Write(ref active, null);
            }
        }
        public static void Record(string kind, in CraneActionReceipt receipt, long mailbox = 0,
            string reason = "", bool hadPending = false, long applicationTick = -1,
            CraneActionPolicy policy = CraneActionPolicy.LatestValid, long maximumLagTicks = -1,
            long decisionEpisode = -1, long rawSeconds = 0, long rawNanoseconds = 0) {
            Buffer b = Volatile.Read(ref active);
            if (b == null || Volatile.Read(ref b.closed) != 0) return;
            RecordTo(b, kind, receipt, mailbox, reason, hadPending, applicationTick, policy,
                maximumLagTicks, decisionEpisode, rawSeconds, rawNanoseconds);
        }
        private static void RecordAccepted(Buffer b, CraneAcceptedAction action) {
            // Delegate snapshots may outlive unsubscribe. The closed-session guard in RecordTo
            // prevents an old delegate from writing into a subsequent session.
            if (!ReferenceEquals(Volatile.Read(ref active), b)) return;
            try {
                long completionTick = CraneRuntimeMetrics.SimulationTick;
                var receipt = new CraneActionReceipt(action.Source, action.EpisodeId,
                    action.Sequence, action.SourceObservationTick, action.ReceiveTick);
                RecordTo(b, "post_apply_callback", receipt, applicationTick: action.ApplicationTick,
                    callbackCompletionTick: completionTick, payloadEncoding: action.Payload.Encoding,
                    payload: action.Payload.Data);
            } catch {
                lock (b.sync) { if (b.closed == 0) { b.attempts++; b.dropped++; } }
            }
        }
        private static void RecordTo(Buffer b, string kind, in CraneActionReceipt receipt,
            long mailbox = 0, string reason = "", bool hadPending = false,
            long applicationTick = -1, CraneActionPolicy policy = CraneActionPolicy.LatestValid,
            long maximumLagTicks = -1, long decisionEpisode = -1, long rawSeconds = 0,
            long rawNanoseconds = 0, long callbackCompletionTick = -1,
            string payloadEncoding = null, byte[] payload = null,
            long snapshotTick = -1, long acceptedActions = -1, long rejectedActions = -1,
            long staleActions = -1, long crossEpisodeActions = -1,
            long duplicateActions = -1, long unknownSourceActions = -1) {
            lock (b.sync) {
                if (b.closed != 0) return;
                b.attempts++;
                int bytes = payload?.Length ?? 0;
                if (b.failed != 0 || b.count >= b.capacity || bytes > b.maximumPayloadBytes ||
                    bytes > b.payloadByteCapacity - b.payloadBytes) { b.dropped++; return; }
                try {
                    byte[] ownedPayload = payload == null ? null : (byte[])payload.Clone();
                    var value = new CraneActionTimingEvent {
                        kind = kind, source = receipt.Source, reason = reason, hadPending = hadPending,
                        ordinal = b.ordinal + 1, monotonic = Stopwatch.GetTimestamp(),
                        episode = receipt.EpisodeId, sequence = receipt.Sequence,
                        sourceTick = receipt.SourceObservationTick, receiveTick = receipt.ReceiveTick,
                        applicationTick = applicationTick, decisionEpisode = decisionEpisode,
                        policy = maximumLagTicks >= 0 ? policy.ToString() : "not_captured",
                        maximumLagTicks = maximumLagTicks, mailbox = mailbox,
                        rawSeconds = rawSeconds, rawNanoseconds = rawNanoseconds,
                        callbackCompletionTick = callbackCompletionTick,
                        payloadEncoding = payloadEncoding, payload = ownedPayload,
                        snapshotTick = snapshotTick, acceptedActions = acceptedActions,
                        rejectedActions = rejectedActions, staleActions = staleActions,
                        crossEpisodeActions = crossEpisodeActions, duplicateActions = duplicateActions,
                        unknownSourceActions = unknownSourceActions
                    };
                    b.queue.Enqueue(value); b.ordinal++; b.count++;
                    b.payloadBytes += bytes; b.enqueued++;
                } catch { b.dropped++; }
            }
        }
        public static bool TryRead(out CraneActionTimingEvent value) {
            Buffer b = Volatile.Read(ref active);
            if (b != null) {
                lock (b.sync) {
                    if (b.queue.TryDequeue(out value)) {
                        b.count--; b.payloadBytes -= value.payload?.Length ?? 0; return true;
                    }
                }
            }
            value = null; return false;
        }
        public static void Drain(TextWriter writer) {
            Buffer b = Volatile.Read(ref active);
            if (b == null || Volatile.Read(ref b.failed) != 0) return;
            try {
                while (TryRead(out CraneActionTimingEvent value)) {
                    try { writer.WriteLine(JsonUtility.ToJson(value)); }
                    catch { lock (b.sync) b.dropped++; throw; }
                    lock (b.sync) b.written++;
                }
                writer.Flush();
            } catch {
                lock (b.sync) {
                    b.failed = 1;
                    while (b.queue.TryDequeue(out var pending)) {
                        b.count--; b.payloadBytes -= pending.payload?.Length ?? 0; b.dropped++;
                    }
                }
            }
        }
        public static void RecordRosCallback(string source, long sequence, long sourceTick,
            long seconds, long nanoseconds) {
            if (!Enabled) return;
            var receipt = new CraneActionReceipt(source, CraneRuntimeMetrics.EpisodeId, sequence,
                sourceTick, CraneRuntimeMetrics.SimulationTick);
            Record("ros_callback", receipt, rawSeconds: seconds, rawNanoseconds: nanoseconds);
        }
        public static void RecordCounterSnapshot(long episode, long snapshotTick,
            long acceptedActions, long rejectedActions, long staleActions,
            long crossEpisodeActions, long duplicateActions, long unknownSourceActions) {
            Buffer b = Volatile.Read(ref active);
            if (b == null || Volatile.Read(ref b.closed) != 0) return;
            var receipt = new CraneActionReceipt("worker", episode, -1, -1, snapshotTick);
            RecordTo(b, "counter_snapshot", receipt, reason: "worker_action_timing_snapshot",
                snapshotTick: snapshotTick, acceptedActions: acceptedActions,
                rejectedActions: rejectedActions, staleActions: staleActions,
                crossEpisodeActions: crossEpisodeActions, duplicateActions: duplicateActions,
                unknownSourceActions: unknownSourceActions);
        }
        public static void MarkWriterFailed() {
            Buffer b = Volatile.Read(ref active);
            if (b != null) lock (b.sync) b.failed = 1;
        }
    }

    public sealed class CraneActionTimingAuditWriter : MonoBehaviour {
        private StreamWriter writer;
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
        private static void Initialize() {
            string[] args = Environment.GetCommandLineArgs();
            int index = Array.IndexOf(args, "--crane-action-timing-audit");
            if (index < 0) return;
            CraneActionTimingAudit.StartBuffer();
            var owner = new GameObject("CraneActionTimingAudit");
            DontDestroyOnLoad(owner);
            var component = owner.AddComponent<CraneActionTimingAuditWriter>();
            try {
                if (index + 1 >= args.Length) throw new ArgumentException("Missing audit path");
                component.writer = new StreamWriter(args[index + 1], false);
                component.writer.WriteLine("{\"kind\":\"metadata\",\"schema\":\"action-timing-v9\",\"clock\":\"same-process-stopwatch\",\"frequency\":" + Stopwatch.Frequency + ",\"capacity\":100000,\"maxPayloadBytes\":65536,\"payloadByteCapacity\":16777216,\"acceptedObserverSubscribed\":true}");
                component.writer.Flush();
            } catch { CraneActionTimingAudit.MarkWriterFailed(); }
        }
        private void LateUpdate() { if (writer != null) CraneActionTimingAudit.Drain(writer); }
        private void OnDestroy() {
            CraneActionTimingAudit.StopRecording();
            if (writer == null) return;
            CraneActionTimingAudit.Drain(writer);
            try {
                writer.WriteLine("{\"kind\":\"footer\",\"dropped\":" + CraneActionTimingAudit.Dropped +
                    ",\"buffered\":" + CraneActionTimingAudit.Buffered +
                    ",\"bufferedPayloadBytes\":" + CraneActionTimingAudit.BufferedPayloadBytes +
                    ",\"written\":" + CraneActionTimingAudit.Written +
                    ",\"enqueued\":" + CraneActionTimingAudit.Enqueued +
                    ",\"eventAttempts\":" + CraneActionTimingAudit.EventAttempts +
                    ",\"acceptedObserverSubscribed\":" + (CraneActionTimingAudit.AcceptedObserverSubscribed ? "true" : "false") +
                    ",\"writerFailed\":" + (CraneActionTimingAudit.WriterFailed ? "true" : "false") + "}");
                writer.Dispose();
            } catch { CraneActionTimingAudit.MarkWriterFailed(); }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Linq;
using Sim.Utils.ROS;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.SceneManagement;

namespace Sim.Utils.Performance {
    public enum CraneEpisodeResetPhase {
        BeforePhysics,
        AfterPhysics
    }

    public readonly struct CraneEpisodeResetContext {
        public readonly long EpisodeId;
        public readonly int Seed;

        internal CraneEpisodeResetContext(long episodeId, int seed) {
            EpisodeId = episodeId;
            Seed = seed;
        }
    }

    /// <summary>
    /// Explicit reset seam for state that Unity cannot infer from a Transform or physics body.
    /// Implementations must be idempotent and must not start asynchronous work while resetting.
    /// </summary>
    public interface ICraneEpisodeResettable {
        int ResetPriority { get; }
        void CaptureEpisodeInitialState();
        void ResetEpisode(in CraneEpisodeResetContext context, CraneEpisodeResetPhase phase);
    }

    public readonly struct CraneEpisodeResetResult {
        public readonly long EpisodeId;
        public readonly int RigidbodyCount;
        public readonly int ArticulationCount;
        public readonly int ResettableCount;
        public readonly double WallMilliseconds;

        internal CraneEpisodeResetResult(long episodeId, int rigidbodyCount,
            int articulationCount, int resettableCount, double wallMilliseconds) {
            EpisodeId = episodeId;
            RigidbodyCount = rigidbodyCount;
            ArticulationCount = articulationCount;
            ResettableCount = resettableCount;
            WallMilliseconds = wallMilliseconds;
        }
    }

    /// <summary>
    /// Captures and restores a single loaded scene without rebuilding it. Scene reload remains the
    /// reference reset until every stateful component in a production scene implements the reset
    /// seam and passes A-B-A equivalence.
    /// </summary>
    public sealed class CraneEpisodeResetCoordinator {
        private readonly struct RigidbodyState {
            public readonly Rigidbody Body;
            public readonly Vector3 Position;
            public readonly Quaternion Rotation;
            public readonly Vector3 LinearVelocity;
            public readonly Vector3 AngularVelocity;
            public readonly bool Sleeping;

            public RigidbodyState(Rigidbody body) {
                Body = body;
                Position = body.position;
                Rotation = body.rotation;
                LinearVelocity = body.linearVelocity;
                AngularVelocity = body.angularVelocity;
                Sleeping = body.IsSleeping();
            }

            public void Restore() {
                if (Body == null) return;
                Body.position = Position;
                Body.rotation = Rotation;
                Body.linearVelocity = LinearVelocity;
                Body.angularVelocity = AngularVelocity;
                if (Sleeping) Body.Sleep();
                else Body.WakeUp();
            }
        }

        private sealed class ArticulationState {
            private readonly ArticulationBody body;
            private readonly Vector3 position;
            private readonly Quaternion rotation;
            private readonly Vector3 linearVelocity;
            private readonly Vector3 angularVelocity;
            private readonly float[] jointPosition;
            private readonly float[] jointVelocity;
            private readonly float[] jointForce;
            private readonly bool sleeping;

            public ArticulationState(ArticulationBody body) {
                this.body = body;
                position = body.transform.position;
                rotation = body.transform.rotation;
                linearVelocity = body.linearVelocity;
                angularVelocity = body.angularVelocity;
                jointPosition = Copy(body.jointPosition);
                jointVelocity = Copy(body.jointVelocity);
                jointForce = Copy(body.jointForce);
                sleeping = body.IsSleeping();
            }

            public void Restore() {
                if (body == null) return;
                if (body.isRoot) body.TeleportRoot(position, rotation);
                body.jointPosition = Restore(body.jointPosition, jointPosition);
                body.jointVelocity = Restore(body.jointVelocity, jointVelocity);
                body.jointForce = Restore(body.jointForce, jointForce);
                body.linearVelocity = linearVelocity;
                body.angularVelocity = angularVelocity;
                if (sleeping) body.Sleep();
                else body.WakeUp();
            }

            private static float[] Copy(ArticulationReducedSpace values) {
                var copy = new float[values.dofCount];
                for (int i = 0; i < copy.Length; i++) copy[i] = values[i];
                return copy;
            }

            private static ArticulationReducedSpace Restore(ArticulationReducedSpace destination,
                float[] source) {
                ArticulationReducedSpace values = destination;
                int count = Math.Min(values.dofCount, source.Length);
                for (int i = 0; i < count; i++) values[i] = source[i];
                return values;
            }
        }

        private readonly List<RigidbodyState> rigidbodies = new();
        private readonly List<ArticulationState> articulations = new();
        private readonly List<ICraneEpisodeResettable> resettables = new();
        private readonly Scene scene;
        private readonly int seed;
        private bool captured;

        public CraneEpisodeResetCoordinator(Scene scene, int seed) {
            if (!scene.IsValid() || !scene.isLoaded)
                throw new ArgumentException("Reset scene must be valid and loaded.", nameof(scene));
            this.scene = scene;
            this.seed = seed;
        }

        public void Capture() {
            rigidbodies.Clear();
            articulations.Clear();
            resettables.Clear();

            foreach (Rigidbody body in UnityEngine.Object.FindObjectsByType<Rigidbody>(
                         FindObjectsInactive.Include, FindObjectsSortMode.InstanceID))
                if (body.gameObject.scene == scene) rigidbodies.Add(new RigidbodyState(body));

            foreach (ArticulationBody body in UnityEngine.Object.FindObjectsByType<ArticulationBody>(
                         FindObjectsInactive.Include, FindObjectsSortMode.InstanceID))
                if (body.gameObject.scene == scene) articulations.Add(new ArticulationState(body));

            resettables.AddRange(UnityEngine.Object.FindObjectsByType<MonoBehaviour>(
                    FindObjectsInactive.Include, FindObjectsSortMode.InstanceID)
                .Where(component => component.gameObject.scene == scene)
                .OfType<ICraneEpisodeResettable>()
                .OrderBy(component => component.ResetPriority));
            foreach (ICraneEpisodeResettable resettable in resettables)
                resettable.CaptureEpisodeInitialState();
            captured = true;
        }

        public CraneEpisodeResetResult Reset() {
            if (!captured) throw new InvalidOperationException("Capture must run before Reset.");
            using var marker = CraneProfiler.EpisodeReset.Auto();
            var stopwatch = Stopwatch.StartNew();

            // Drain callbacks while the old generation is still current, then advance the
            // generation so a late transport callback cannot affect the new episode.
            AsyncGPUReadback.WaitAllRequests();
            long episodeId = CraneRuntimeMetrics.BeginEpisode();
            CraneActionGate.BeginEpisode();
            UnityEngine.Random.InitState(seed);
            var context = new CraneEpisodeResetContext(episodeId, seed);

            foreach (ICraneEpisodeResettable resettable in resettables)
                resettable.ResetEpisode(context, CraneEpisodeResetPhase.BeforePhysics);
            foreach (RigidbodyState state in rigidbodies) state.Restore();
            foreach (ArticulationState state in articulations) state.Restore();
            Physics.SyncTransforms();
            foreach (ICraneEpisodeResettable resettable in resettables)
                resettable.ResetEpisode(context, CraneEpisodeResetPhase.AfterPhysics);

            stopwatch.Stop();
            return new CraneEpisodeResetResult(episodeId, rigidbodies.Count,
                articulations.Count, resettables.Count, stopwatch.Elapsed.TotalMilliseconds);
        }
    }
}

using System;

namespace Sim.Utils.Performance {
    /// <summary>
    /// Compact provenance for an acquired observation. Payload bytes are intentionally not held
    /// here: the replay recorder can subscribe without extending the lifetime of camera/cloud data.
    /// </summary>
    public readonly struct CraneObservationMetadata {
        public readonly string Source;
        public readonly string Topic;
        public readonly string FrameId;
        public readonly string MessageType;
        public readonly string Encoding;
        public readonly string PayloadPolicy;
        public readonly long EpisodeId;
        public readonly long Sequence;
        public readonly long AcquisitionTick;
        public readonly double AcquisitionTime;
        public readonly long CompletionTick;
        public readonly double CompletionTime;
        public readonly int Width;
        public readonly int Height;
        public readonly int RowStep;
        public readonly int ElementCount;
        public readonly long PayloadBytes;

        public CraneObservationMetadata(string source, string topic, string frameId,
            string messageType, string encoding, string payloadPolicy, long episodeId,
            long sequence, long acquisitionTick, double acquisitionTime, long completionTick,
            double completionTime, int width, int height, int rowStep, int elementCount,
            long payloadBytes) {
            Source = source ?? string.Empty;
            Topic = topic ?? string.Empty;
            FrameId = frameId ?? string.Empty;
            MessageType = messageType ?? string.Empty;
            Encoding = encoding ?? string.Empty;
            PayloadPolicy = payloadPolicy ?? string.Empty;
            EpisodeId = episodeId;
            Sequence = sequence;
            AcquisitionTick = acquisitionTick;
            AcquisitionTime = acquisitionTime;
            CompletionTick = completionTick;
            CompletionTime = completionTime;
            Width = width;
            Height = height;
            RowStep = rowStep;
            ElementCount = elementCount;
            PayloadBytes = payloadBytes;
        }
    }

    /// <summary>
    /// Process-local observation event stream. Subscribers must copy metadata synchronously and
    /// must never retain sensor payloads; this keeps recording memory bounded.
    /// </summary>
    public static class CraneObservationJournal {
        private static readonly object s_Lock = new();
        private static Action<CraneObservationMetadata> s_Handlers;

        public static void Subscribe(Action<CraneObservationMetadata> handler) {
            if (handler == null) return;
            lock (s_Lock) s_Handlers += handler;
        }

        public static void Unsubscribe(Action<CraneObservationMetadata> handler) {
            if (handler == null) return;
            lock (s_Lock) s_Handlers -= handler;
        }

        public static void Report(in CraneObservationMetadata metadata) {
            Action<CraneObservationMetadata> handlers;
            lock (s_Lock) handlers = s_Handlers;
            handlers?.Invoke(metadata);
        }
    }
}

