        private static readonly object s_LidarLock = new();
        private static readonly object s_ImageLock = new();
        private static long s_EpisodeId;
        private static long s_SimulationTick;
        private static long s_ObservationTick = -1;
        private static long s_ActionSourceTick = -1;
        private static long s_ActionReceiveTick = -1;
        private static long s_ActionApplicationTick = -1;
        private static long s_ActionSequence = -1;
        private static long s_AcceptedActions;
        private static long s_RejectedActions;
        private static long s_UnknownSourceActions;
        private static long s_CrossEpisodeActions;
        private static long s_DuplicateActions;
        private static long s_StaleObservations;
        private static long s_StaleActions;
        private static long s_KnownSourceActions;
        private static long s_SourceToApplicationTicks;
        private static long s_MaximumSourceToApplicationTicks;
        private static long s_ReceiveToApplicationTicks;
        private static long s_MaximumReceiveToApplicationTicks;
        private static long s_LastActionApplicationTick = -1;
        private static long s_MaximumInterApplicationTicks;
        private static long s_CommandTimeouts;
        private static long s_SitlValidServoPackets;
        private static long s_SitlInvalidServoPackets;
        private static long s_SitlTelemetryPackets;
        private static long s_SitlLastFrame = -1;
        private static long s_SitlLastTelemetryTimestampMicroseconds = -1;
        private static long s_FailedObservations;
        private static long s_LidarScanCount;
        private static int s_LidarConfiguredPoints;
        private static int s_LidarBatchSize;
        private static long s_LidarTotalPoints;
        private static long s_LidarHits;
        private static long s_LidarMisses;
        private static float s_LidarMinimumRange = float.PositiveInfinity;
        private static float s_LidarMaximumRange;
        private static double s_LidarRangeSum;
        private static ulong s_LidarChecksum = 14695981039346656037UL;
        private static long s_LidarAcquisitionTick = -1;
        private static long s_LidarCommandValidationCount;
        private static long s_LidarCommandValidationMismatches;
        private static long s_LidarPackValidationBytes;
        private static long s_LidarPackValidationMismatches;
        private static long s_LidarProcessValidationCount;
        private static long s_LidarProcessValidationMismatches;
        private static long s_DepthBufferValidationBytes;
        private static long s_DepthBufferValidationMismatches;
        private static readonly long[] s_ImageAcquisitionCount = new long[2];
        private static readonly int[] s_ImageWidth = new int[2];
        private static readonly int[] s_ImageHeight = new int[2];
        private static readonly long[] s_ImageTotalBytes = new long[2];
        private static readonly ulong[] s_ImageChecksum = { 14695981039346656037UL, 14695981039346656037UL };
        private static readonly long[] s_ImageAcquisitionTick = { -1, -1 };
        private static long s_DetectionAcquisitionCount;
        private static long s_DetectionCount;
        private static long s_DetectionAcquisitionTick = -1;

        public static long EpisodeId => Interlocked.Read(ref s_EpisodeId);
        public static long SimulationTick => Interlocked.Read(ref s_SimulationTick);
        public static long ObservationTick => Interlocked.Read(ref s_ObservationTick);
        public static long ActionSourceTick => Interlocked.Read(ref s_ActionSourceTick);
        public static long ActionReceiveTick => Interlocked.Read(ref s_ActionReceiveTick);
        public static long ActionApplicationTick => Interlocked.Read(ref s_ActionApplicationTick);
        public static long ActionSequence => Interlocked.Read(ref s_ActionSequence);
        public static long AcceptedActions => Interlocked.Read(ref s_AcceptedActions);
        public static long RejectedActions => Interlocked.Read(ref s_RejectedActions);
        public static long UnknownSourceActions => Interlocked.Read(ref s_UnknownSourceActions);
        public static long CrossEpisodeActions => Interlocked.Read(ref s_CrossEpisodeActions);
        public static long DuplicateActions => Interlocked.Read(ref s_DuplicateActions);
        public static long StaleObservations => Interlocked.Read(ref s_StaleObservations);
        public static long StaleActions => Interlocked.Read(ref s_StaleActions);
        public static long FailedObservations => Interlocked.Read(ref s_FailedObservations);
        public static long LidarCommandValidationCount =>
            Interlocked.Read(ref s_LidarCommandValidationCount);
        public static long LidarCommandValidationMismatches =>
            Interlocked.Read(ref s_LidarCommandValidationMismatches);
        public static long LidarPackValidationBytes =>
            Interlocked.Read(ref s_LidarPackValidationBytes);
        public static long LidarPackValidationMismatches =>
            Interlocked.Read(ref s_LidarPackValidationMismatches);
        public static long LidarProcessValidationCount =>
            Interlocked.Read(ref s_LidarProcessValidationCount);
        public static long LidarProcessValidationMismatches =>
            Interlocked.Read(ref s_LidarProcessValidationMismatches);
        public static long DepthBufferValidationBytes =>
            Interlocked.Read(ref s_DepthBufferValidationBytes);
        public static long DepthBufferValidationMismatches =>
            Interlocked.Read(ref s_DepthBufferValidationMismatches);

        public static long AdvanceSimulationTick() => Interlocked.Increment(ref s_SimulationTick);
        public static void ReportObservation(long tick) => Interlocked.Exchange(ref s_ObservationTick, tick);
        public static void ReportActionReceived(long receiveTick, bool sourceUnknown) {
            Interlocked.Exchange(ref s_ActionReceiveTick, receiveTick);
            if (sourceUnknown) Interlocked.Increment(ref s_UnknownSourceActions);
        }
        public static void ReportAction(long sourceTick, long receiveTick, long applicationTick,
            long sequence) {
            Interlocked.Exchange(ref s_ActionSourceTick, sourceTick);
            Interlocked.Exchange(ref s_ActionReceiveTick, receiveTick);
            Interlocked.Exchange(ref s_ActionApplicationTick, applicationTick);
            Interlocked.Exchange(ref s_ActionSequence, sequence);
            Interlocked.Increment(ref s_AcceptedActions);
            long receiveLag = System.Math.Max(0, applicationTick - receiveTick);
            Interlocked.Add(ref s_ReceiveToApplicationTicks, receiveLag);
            ReportMaximum(ref s_MaximumReceiveToApplicationTicks, receiveLag);
            if (sourceTick >= 0) {
                long sourceLag = System.Math.Max(0, applicationTick - sourceTick);
                Interlocked.Increment(ref s_KnownSourceActions);
                Interlocked.Add(ref s_SourceToApplicationTicks, sourceLag);
                ReportMaximum(ref s_MaximumSourceToApplicationTicks, sourceLag);
            }
            long previousApplicationTick = Interlocked.Exchange(
                ref s_LastActionApplicationTick, applicationTick);
            if (previousApplicationTick >= 0)
                ReportMaximum(ref s_MaximumInterApplicationTicks,
                    System.Math.Max(0, applicationTick - previousApplicationTick));
        }
        public static void ReportCommandTimeout() => Interlocked.Increment(ref s_CommandTimeouts);

        public static void ReportSitlServoPacket(bool valid, long frame) {
            if (valid) {
                Interlocked.Increment(ref s_SitlValidServoPackets);
                Interlocked.Exchange(ref s_SitlLastFrame, frame);
            }
            else {
                Interlocked.Increment(ref s_SitlInvalidServoPackets);
            }
        }

        public static void ReportSitlTelemetry(double simulatedTimestamp) {
            Interlocked.Increment(ref s_SitlTelemetryPackets);
            Interlocked.Exchange(ref s_SitlLastTelemetryTimestampMicroseconds,
                (long)System.Math.Round(simulatedTimestamp * 1_000_000.0));
        }

        public static ActionTimingSnapshot GetActionTimingSnapshot() => new(
            Interlocked.Read(ref s_AcceptedActions),
            Interlocked.Read(ref s_KnownSourceActions),
            Interlocked.Read(ref s_SourceToApplicationTicks),
            Interlocked.Read(ref s_MaximumSourceToApplicationTicks),
            Interlocked.Read(ref s_ReceiveToApplicationTicks),
            Interlocked.Read(ref s_MaximumReceiveToApplicationTicks),
            Interlocked.Read(ref s_MaximumInterApplicationTicks),
            Interlocked.Read(ref s_CommandTimeouts));

        public static SitlSnapshot GetSitlSnapshot() => new(
            Interlocked.Read(ref s_SitlValidServoPackets),
            Interlocked.Read(ref s_SitlInvalidServoPackets),
            Interlocked.Read(ref s_SitlTelemetryPackets),
            Interlocked.Read(ref s_SitlLastFrame),
            Interlocked.Read(ref s_SitlLastTelemetryTimestampMicroseconds));

        private static void ReportMaximum(ref long destination, long value) {
            long current = Interlocked.Read(ref destination);
            while (value > current) {
                long observed = Interlocked.CompareExchange(ref destination, value, current);
                if (observed == current) return;
                current = observed;
            }
        }
        public static void ReportRejectedAction(CraneActionRejection rejection) {
            Interlocked.Increment(ref s_RejectedActions);
            if (rejection == CraneActionRejection.Stale)
                Interlocked.Increment(ref s_StaleActions);
            else if (rejection == CraneActionRejection.CrossEpisode)
                Interlocked.Increment(ref s_CrossEpisodeActions);
            else if (rejection == CraneActionRejection.DuplicateOrOutOfOrder)
                Interlocked.Increment(ref s_DuplicateActions);
        }
        public static void ReportStaleObservation() => Interlocked.Increment(ref s_StaleObservations);
        public static void ReportFailedObservation() => Interlocked.Increment(ref s_FailedObservations);

        public static void ReportLidarScan(int configuredPoints, int batchSize, int hits, int misses,
            float minimumRange, float maximumRange, double rangeSum, ulong checksum, long acquisitionTick) {
            lock (s_LidarLock) {
                s_LidarScanCount++;
                s_LidarConfiguredPoints = configuredPoints;
                s_LidarBatchSize = batchSize;
                s_LidarTotalPoints += configuredPoints;
                s_LidarHits += hits;
                s_LidarMisses += misses;
                if (hits > 0) {
                    if (minimumRange < s_LidarMinimumRange) s_LidarMinimumRange = minimumRange;
                    if (maximumRange > s_LidarMaximumRange) s_LidarMaximumRange = maximumRange;
                    s_LidarRangeSum += rangeSum;
                }
                s_LidarChecksum ^= checksum;
                s_LidarChecksum *= 1099511628211UL;
                s_LidarAcquisitionTick = acquisitionTick;
            }
        }

        public static LidarSnapshot GetLidarSnapshot() {
            lock (s_LidarLock) {
                return new LidarSnapshot(s_LidarScanCount, s_LidarConfiguredPoints, s_LidarBatchSize,
                    s_LidarTotalPoints,
                    s_LidarHits, s_LidarMisses,
                    float.IsPositiveInfinity(s_LidarMinimumRange) ? 0 : s_LidarMinimumRange,
                    s_LidarMaximumRange, s_LidarHits == 0 ? 0 : s_LidarRangeSum / s_LidarHits,
                    s_LidarChecksum, s_LidarAcquisitionTick);
            }
        }

        public static void ReportLidarCommandValidation(int compared, int mismatches) {
            Interlocked.Add(ref s_LidarCommandValidationCount, compared);
            Interlocked.Add(ref s_LidarCommandValidationMismatches, mismatches);
        }

        public static void ReportLidarPackValidation(int bytes, int mismatches) {
            Interlocked.Add(ref s_LidarPackValidationBytes, bytes);
            Interlocked.Add(ref s_LidarPackValidationMismatches, mismatches);
        }

        public static void ReportLidarProcessValidation(int compared, int mismatches) {
            Interlocked.Add(ref s_LidarProcessValidationCount, compared);
            Interlocked.Add(ref s_LidarProcessValidationMismatches, mismatches);
        }

        public static void ReportDepthBufferValidation(int bytes, int mismatches) {
            Interlocked.Add(ref s_DepthBufferValidationBytes, bytes);
            Interlocked.Add(ref s_DepthBufferValidationMismatches, mismatches);
        }

        public static void ReportImage(bool depth, int width, int height, byte[] data, long acquisitionTick) {
            int index = depth ? 1 : 0;
            ulong checksum = 14695981039346656037UL;
            if (CaptureImageSignatures) {
                for (int i = 0; i < data.Length; i++) {
                    checksum ^= data[i];
                    checksum *= 1099511628211UL;
                }
            }
            lock (s_ImageLock) {
                s_ImageAcquisitionCount[index]++;
                s_ImageWidth[index] = width;
                s_ImageHeight[index] = height;
                s_ImageTotalBytes[index] += data.Length;
                s_ImageChecksum[index] ^= checksum;
                s_ImageChecksum[index] *= 1099511628211UL;
                s_ImageAcquisitionTick[index] = acquisitionTick;
            }
        }

        public static ImageSnapshot GetImageSnapshot(bool depth) {
            int index = depth ? 1 : 0;
            lock (s_ImageLock) {
                return new ImageSnapshot(s_ImageAcquisitionCount[index], s_ImageWidth[index],
                    s_ImageHeight[index], s_ImageTotalBytes[index], s_ImageChecksum[index],
                    s_ImageAcquisitionTick[index]);
            }
        }

        public static void ReportDetections(int count, long acquisitionTick) {
            Interlocked.Increment(ref s_DetectionAcquisitionCount);
            Interlocked.Add(ref s_DetectionCount, count);
            Interlocked.Exchange(ref s_DetectionAcquisitionTick, acquisitionTick);
        }

        public static DetectionSnapshot GetDetectionSnapshot() => new(
            Interlocked.Read(ref s_DetectionAcquisitionCount),
            Interlocked.Read(ref s_DetectionCount),
            Interlocked.Read(ref s_DetectionAcquisitionTick));

        public static long BeginEpisode() {
            Sim.Utils.ROS.Clock.BeginEpisode();
            Interlocked.Exchange(ref s_SimulationTick, 0);
            Interlocked.Exchange(ref s_ObservationTick, -1);
            Interlocked.Exchange(ref s_ActionSourceTick, -1);
            Interlocked.Exchange(ref s_ActionReceiveTick, -1);
            Interlocked.Exchange(ref s_ActionApplicationTick, -1);
            Interlocked.Exchange(ref s_ActionSequence, -1);
            Interlocked.Exchange(ref s_AcceptedActions, 0);
            Interlocked.Exchange(ref s_RejectedActions, 0);
            Interlocked.Exchange(ref s_UnknownSourceActions, 0);
            Interlocked.Exchange(ref s_CrossEpisodeActions, 0);
            Interlocked.Exchange(ref s_DuplicateActions, 0);
            Interlocked.Exchange(ref s_StaleObservations, 0);
            Interlocked.Exchange(ref s_StaleActions, 0);
            Interlocked.Exchange(ref s_KnownSourceActions, 0);
            Interlocked.Exchange(ref s_SourceToApplicationTicks, 0);
            Interlocked.Exchange(ref s_MaximumSourceToApplicationTicks, 0);
            Interlocked.Exchange(ref s_ReceiveToApplicationTicks, 0);
            Interlocked.Exchange(ref s_MaximumReceiveToApplicationTicks, 0);
            Interlocked.Exchange(ref s_LastActionApplicationTick, -1);
            Interlocked.Exchange(ref s_MaximumInterApplicationTicks, 0);
            Interlocked.Exchange(ref s_CommandTimeouts, 0);
            Interlocked.Exchange(ref s_SitlValidServoPackets, 0);
            Interlocked.Exchange(ref s_SitlInvalidServoPackets, 0);
            Interlocked.Exchange(ref s_SitlTelemetryPackets, 0);
            Interlocked.Exchange(ref s_SitlLastFrame, -1);
            Interlocked.Exchange(ref s_SitlLastTelemetryTimestampMicroseconds, -1);
            Interlocked.Exchange(ref s_FailedObservations, 0);
            lock (s_LidarLock) {
                s_LidarScanCount = 0;
                s_LidarConfiguredPoints = 0;
                s_LidarBatchSize = 0;
                s_LidarTotalPoints = 0;
                s_LidarHits = 0;
                s_LidarMisses = 0;
                s_LidarMinimumRange = float.PositiveInfinity;
                s_LidarMaximumRange = 0;
                s_LidarRangeSum = 0;
                s_LidarChecksum = 14695981039346656037UL;
                s_LidarAcquisitionTick = -1;
            }
            Interlocked.Exchange(ref s_LidarCommandValidationCount, 0);
            Interlocked.Exchange(ref s_LidarCommandValidationMismatches, 0);
            Interlocked.Exchange(ref s_LidarPackValidationBytes, 0);
            Interlocked.Exchange(ref s_LidarPackValidationMismatches, 0);
            Interlocked.Exchange(ref s_LidarProcessValidationCount, 0);
            Interlocked.Exchange(ref s_LidarProcessValidationMismatches, 0);
            Interlocked.Exchange(ref s_DepthBufferValidationBytes, 0);
            Interlocked.Exchange(ref s_DepthBufferValidationMismatches, 0);
            lock (s_ImageLock) {
                for (int i = 0; i < 2; i++) {
                    s_ImageAcquisitionCount[i] = 0;
                    s_ImageWidth[i] = 0;
                    s_ImageHeight[i] = 0;
                    s_ImageTotalBytes[i] = 0;
                    s_ImageChecksum[i] = 14695981039346656037UL;
                    s_ImageAcquisitionTick[i] = -1;
                }
            }
            Interlocked.Exchange(ref s_DetectionAcquisitionCount, 0);
            Interlocked.Exchange(ref s_DetectionCount, 0);
            Interlocked.Exchange(ref s_DetectionAcquisitionTick, -1);
            return Interlocked.Increment(ref s_EpisodeId);
        }
    }
}

using System;
using UnityEngine;
using UnityEngine.SceneManagement;

namespace Sim.Utils.Performance {
    /// <summary>
    /// Owns the authoritative fixed-step counter for normal runtime execution. The counter is
    /// independent of benchmark warmup/measurement state and advances exactly once per Unity
    /// FixedUpdate. Scene loads establish a new episode generation before scene Start methods.
    /// </summary>
    [DefaultExecutionOrder(-32700)]
    internal sealed class CraneSimulationClock : MonoBehaviour {
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
        private static void Install() {
            // The provenance fixture advances a synthetic clock explicitly and must remain
            // isolated from Unity lifecycle ticks.
            if (Array.IndexOf(Environment.GetCommandLineArgs(),
                    "--crane-action-validation") >= 0) return;
            var host = new GameObject("CRANE Simulation Clock");
            DontDestroyOnLoad(host);
            host.AddComponent<CraneSimulationClock>();
        }

        private void Awake() => SceneManager.sceneLoaded += OnSceneLoaded;

        private static void OnSceneLoaded(Scene scene, LoadSceneMode mode) =>
            CraneRuntimeMetrics.BeginEpisode();

        private void FixedUpdate() => CraneRuntimeMetrics.AdvanceSimulationTick();

        private void OnDestroy() => SceneManager.sceneLoaded -= OnSceneLoaded;
    }
}

using System;
using UnityEngine;

namespace Sim.Utils.ROS {
    public static class Clock {
        // Since UnityScaled is the default Unity Time mode, we'll use that for this project
        // None of the other time modes are fully validated and guaranteed to be without issues
        public enum ClockMode {
            // Time delta scaled by simulation speed to the start of the current frame, since the beginning of the game
            UnityScaled,
            // Real time delta to the exact moment this function is called, since beginning of the game
            // UnityUnscaled,
            // Real time delta since the Unix Epoch (1/1/1970 @ midnight)
            // UnixEpoch,
            // Examples of other potentially useful clock modes...
            // UnixEpochUtc,
            // DateTimeNow,
            // DateTimeNowUtc,
            // ExternalClock
        }

        public const double k_NanoSecondsInSeconds = 1e9;

        static readonly DateTime k_UnixEpoch = new DateTime(1970, 1, 1, 0, 0, 0, 0);
        // Time the application started, relative to Unix Epoch
        static readonly double k_StartTimeEpochSeconds = SecondsSinceUnixEpoch - Time.realtimeSinceStartupAsDouble;
        static double s_EpisodeStartScaledTime;

        static double SecondsSinceUnixEpoch => (DateTime.Now - k_UnixEpoch).TotalSeconds;
        static double UnityUnscaledTimeSinceFrameStart =>
            Time.realtimeSinceStartupAsDouble - Time.unscaledTimeAsDouble;

        public static double TimeSinceFrameStart => Now - FrameStartTimeInSeconds;

        public static double FrameStartTimeInSeconds {
            get {
                return Mode switch {
                    // This might be an approximation... needs testing.
                    ClockMode.UnityScaled => Math.Max(0, Time.timeAsDouble - s_EpisodeStartScaledTime),
                    // ClockMode.UnityUnscaled => Time.unscaledTimeAsDouble,
                    // ClockMode.UnixEpoch => k_StartTimeEpochSeconds + UnityUnscaledTimeSinceFrameStart,
                    _ => throw new NotImplementedException()
                };
            }
        }

        public static double NowTimeInSeconds {
            get {
                return Mode switch {
                    ClockMode.UnityScaled => Math.Max(0, Time.timeAsDouble - s_EpisodeStartScaledTime) +
                                             UnityUnscaledTimeSinceFrameStart * Time.timeScale,
                    // ClockMode.UnityUnscaled => Time.realtimeSinceStartupAsDouble,
                    // ClockMode.UnixEpoch => SecondsSinceUnixEpoch,
                    _ => throw new NotImplementedException()
                };
            }
        }

        // NOTE: Precision loss vs. other time measurements due to no deltaTimeAsDouble interface
        public static float DeltaTimeInSeconds {
            get {
                return Mode switch {
                    ClockMode.UnityScaled => Time.deltaTime,
                    _ => Time.unscaledDeltaTime,
                };
            }
        }

        public static ClockMode Mode = ClockMode.UnityScaled;

        // Simple interfaces for supporting commonly used vocabulary
        public static double Now => NowTimeInSeconds;
        public static double time => FrameStartTimeInSeconds;
        public static float deltaTime => DeltaTimeInSeconds;

        /// <summary>Starts the ROS/sensor clock at zero for a new authoritative episode.</summary>
        public static void BeginEpisode() => s_EpisodeStartScaledTime = Time.timeAsDouble;

        // WARNING: These functions could potentially mess up threaded access to this clock class.
        //          Would need to include some mutex locking to keep these calls thread-safe
        public static double GetFrameTime(ClockMode temporaryMode) {
            var originalMode = Mode;
            Mode = temporaryMode;
            var t = FrameStartTimeInSeconds;
            Mode = originalMode;
            return t;
        }

        public static double GetNowTime(ClockMode temporaryMode) {
            var originalMode = Mode;
            Mode = temporaryMode;
            var t = NowTimeInSeconds;
            Mode = originalMode;
            return t;
        }
    }
}

using System;
using UnityEngine;
using Unity.Robotics.ROSTCPConnector;
using RosMessageTypes.BuiltinInterfaces;
using RosMessageTypes.Rosgraph;

namespace Sim.Utils.ROS {
    public class ROSClock : MonoBehaviour, Sim.Utils.Performance.ICraneEpisodeResettable {
        private static ROSClock s_Owner;
        [SerializeField] private Clock.ClockMode clockMode;

        [SerializeField, HideInInspector] private Clock.ClockMode lastSetClockMode;

        [SerializeField] private double publishRateHz = 100f;

        private double lastPublishTimeSeconds;
        private long publisherEpisodeId;

        ROSConnection ros;

        private double PublishPeriodSeconds => 1.0f / publishRateHz;
        public int ResetPriority => -90;

        public void CaptureEpisodeInitialState() { }

        public void ResetEpisode(in Sim.Utils.Performance.CraneEpisodeResetContext context,
            Sim.Utils.Performance.CraneEpisodeResetPhase phase) {
            if (phase == Sim.Utils.Performance.CraneEpisodeResetPhase.BeforePhysics)
                lastPublishTimeSeconds = -PublishPeriodSeconds;
        }

        private bool ShouldPublishMessage => Clock.FrameStartTimeInSeconds - PublishPeriodSeconds > lastPublishTimeSeconds;

        private void OnValidate() {
            var clocks = FindObjectsByType<ROSClock>(FindObjectsSortMode.None);
            if (clocks.Length > 1) {
                Debug.LogWarning("Found too many clock publishers in the scene, there should only be one!");
            }

            if (Application.isPlaying && lastSetClockMode != clockMode) {
                Debug.LogWarning("Can't change ClockMode during simulation! Setting it back...");
                clockMode = lastSetClockMode;
            }

            SetClockMode(clockMode);
        }

        private void SetClockMode(Clock.ClockMode mode) {
            Clock.Mode = mode;
            lastSetClockMode = mode;
        }

        // Start is called before the first frame update
        private void Start() {
            if (s_Owner != null && s_Owner != this) {
                Debug.LogWarning($"Disabling duplicate ROSClock on {name}; {s_Owner.name} " +
                                 "already owns the process simulation clock.");
                enabled = false;
                return;
            }
            s_Owner = this;
            publisherEpisodeId = Sim.Utils.Performance.CraneRuntimeMetrics.EpisodeId;
            Debug.Log($"CRANE_ROS_CLOCK_OWNER scene={gameObject.scene.name} " +
                      $"path={StablePath(transform)} entity={GetEntityId()}");
            SetClockMode(clockMode);
            ros = ROSConnection.GetOrCreateInstance();
            ros.RegisterPublisher<ClockMsg>("clock");
        }

        private static string StablePath(Transform value) {
            string path = string.Empty;
            for (Transform current = value; current != null; current = current.parent) {
                string segment = $"{current.GetSiblingIndex()}:{current.name}";
                path = string.IsNullOrEmpty(path) ? segment : segment + "/" + path;
            }
            return path;
        }

        private void PublishMessage() {
            var publishTime = Clock.time;
            var clockMsg = new TimeMsg {
                sec = (int)publishTime,
                nanosec = (uint)((publishTime - Math.Floor(publishTime)) * Clock.k_NanoSecondsInSeconds)
            };
            lastPublishTimeSeconds = publishTime;
            ros.Publish("clock", clockMsg);
        }

        private void Update() {
            // Measurement can start a fresh clock epoch without resetting scene bodies.
            if (publisherEpisodeId != Sim.Utils.Performance.CraneRuntimeMetrics.EpisodeId) {
                publisherEpisodeId = Sim.Utils.Performance.CraneRuntimeMetrics.EpisodeId;
                lastPublishTimeSeconds = -PublishPeriodSeconds;
            }
            if (ShouldPublishMessage) {
                PublishMessage();
            }
        }


        private void OnDestroy() {
            if (s_Owner == this) s_Owner = null;
        }
    }
}

using System;
using System.Reflection;
using UnityEngine;
using Unity.Robotics.ROSTCPConnector;
using RosMessageTypes.Std;
using RosMessageTypes.Sensor;
using Sim.Utils.Performance;
using System.Linq;

namespace Sim.Utils.ROS {
    [AddComponentMenu("")]
    public class ROSPublisher : MonoBehaviour, ICraneEpisodeResettable {
        public static bool TransportSuppressed =>
            Environment.GetCommandLineArgs().Contains("--crane-disable-ros") ||
            Environment.GetCommandLineArgs().Contains("--crane-disable-ros-tcp");
        public string topicName { get; set; }
        public string frameId { get; set; }
        public float Hz;
        public bool manualPublish;

        private ROSConnection ros;
        private float time;

        private Func<object> createMessage;
        private Action<string, object> publishTyped;
        private long observationSequence;
        private long observationEpisode = -1;
        public int ResetPriority => -100;

        public void CaptureEpisodeInitialState() { }

        public void ResetEpisode(in CraneEpisodeResetContext context,
            CraneEpisodeResetPhase phase) {
            if (phase != CraneEpisodeResetPhase.BeforePhysics) return;
            time = 0;
            observationSequence = 0;
            observationEpisode = context.EpisodeId;
        }

        private static void PublishWrapper<T>(ROSConnection ros, string topic, object msg)
        where T : Unity.Robotics.ROSTCPConnector.MessageGeneration.Message {
            ros.Publish(topic, (T)msg);
        }

        private void OnEnable() { hideFlags = HideFlags.HideInInspector; }

        public void Initialize<T>(string topicName, string frameId, Func<T> createMessage, float Hz=10f, bool manualPublish=false)
        where T : Unity.Robotics.ROSTCPConnector.MessageGeneration.Message {
            this.topicName = topicName;
            this.frameId = frameId;
            this.Hz = Hz;
            this.manualPublish = manualPublish;

            this.createMessage = () => createMessage();

            if (TransportSuppressed) return;

            ros = ROSConnection.GetOrCreateInstance();
            ros.RegisterPublisher<T>(topicName);

            var wrapperMethod = typeof(ROSPublisher)
                .GetMethod(nameof(PublishWrapper), BindingFlags.Static | BindingFlags.NonPublic)
                .MakeGenericMethod(typeof(T));

            publishTyped = (Action<string, object>)
                Delegate.CreateDelegate(
                    typeof(Action<string, object>),
                    ros,
                    wrapperMethod
                );
        }

        private void FixedUpdate() {
            if (manualPublish) return;
            if (createMessage == null) return;

            time += Time.fixedDeltaTime;
            if (time >= 1f / Hz) {
                Publish();
                // Preserve the fractional remainder so configured sensor rates do not
                // drift down when their period is not a multiple of fixedDeltaTime.
                time -= 1f / Hz;
            }
        }

        public void Publish() => Publish(CraneRuntimeMetrics.SimulationTick,
            Clock.time);

        /// <summary>
        /// Publishes an observation while preserving when it was acquired. Async sensors must use
        /// this overload because completion can occur several simulation ticks after acquisition.
        /// </summary>
        public void Publish(long acquisitionTick, double acquisitionTime) {
            object message;
            using (CraneProfiler.RosCreateMessage.Auto()) {
                message = createMessage();
            }
            ReportObservation(message, acquisitionTick, acquisitionTime);
            using (CraneProfiler.RosPublish.Auto()) {
                if (!TransportSuppressed) publishTyped(topicName, message);
            }
        }

        private void ReportObservation(object message, long acquisitionTick,
            double acquisitionTime) {
            long episode = CraneRuntimeMetrics.EpisodeId;
            if (observationEpisode != episode) {
                observationEpisode = episode;
                observationSequence = 0;
            }

            int width = 0;
            int height = 0;
            int rowStep = 0;
            int elements = 0;
            long payloadBytes = 0;
            string encoding = string.Empty;
            switch (message) {
                case ImageMsg image:
                    width = checked((int)image.width);
                    height = checked((int)image.height);
                    rowStep = checked((int)image.step);
                    elements = checked(width * height);
                    payloadBytes = image.data?.LongLength ?? 0;
                    encoding = image.encoding ?? string.Empty;
                    break;
                case PointCloud2Msg cloud:
                    width = checked((int)cloud.width);
                    height = checked((int)cloud.height);
                    rowStep = checked((int)cloud.row_step);
                    elements = checked(width * height);
                    payloadBytes = cloud.data?.LongLength ?? 0;
                    encoding = "sensor_msgs/PointCloud2";
                    break;
                case LaserScanMsg scan:
                    elements = scan.ranges?.Length ?? 0;
                    payloadBytes = (long)elements * sizeof(float);
                    encoding = "sensor_msgs/LaserScan:float32";
                    break;
            }
            if (message?.GetType().FullName == "RosMessageTypes.Vision.Detection3DArrayMsg") {
                FieldInfo detectionsField = message.GetType().GetField("detections");
                if (detectionsField?.GetValue(message) is Array detectionArray)
                    elements = detectionArray.Length;
                encoding = "vision_msgs/Detection3DArray";
            }

            var metadata = new CraneObservationMetadata(
                StableSourcePath(), topicName, frameId,
                message?.GetType().FullName ?? string.Empty, encoding,
                "metadata-only:regenerate-from-authoritative-state",
                episode, ++observationSequence, acquisitionTick, acquisitionTime,
                CraneRuntimeMetrics.SimulationTick, Clock.time,
                width, height, rowStep, elements, payloadBytes);
            CraneObservationJournal.Report(metadata);
        }

        private string StableSourcePath() {
            Transform current = transform;
            string path = string.Empty;
            while (current != null) {
                string segment = $"{current.GetSiblingIndex()}:{current.name}";
                path = string.IsNullOrEmpty(path) ? segment : segment + "/" + path;
                current = current.parent;
            }
            return $"{gameObject.scene.path}|{path}|{GetType().FullName}";
        }

        public HeaderMsg CreateHeader() {
            var header = new HeaderMsg { frame_id=frameId };
            var publishTime = Clock.Now;
            var sec = publishTime;
            var nanosec = (publishTime - Math.Floor(publishTime)) * Clock.k_NanoSecondsInSeconds;
            header.stamp.sec = (int)sec;
            header.stamp.nanosec = (uint)nanosec;
            return header;
        }
    }
}

using System;
using UnityEngine;
using Unity.Robotics.ROSTCPConnector;

namespace Sim.Utils.ROS {
    [Serializable]
    public class ROSSubscriber : MonoBehaviour {
        public string topicName;

        public void Initialize<T>(string topicName, Action<T> callback)
        where T : Unity.Robotics.ROSTCPConnector.MessageGeneration.Message {
            this.topicName = topicName;
            if (ROSPublisher.TransportSuppressed) return;
            ROSConnection.GetOrCreateInstance().Subscribe(topicName, callback);
        }

        public void Initialize<T>(Action<T> callback)
        where T : Unity.Robotics.ROSTCPConnector.MessageGeneration.Message {
            if (topicName == null) { Debug.LogError("No topic name set"); return; }
            if (ROSPublisher.TransportSuppressed) return;
            ROSConnection.GetOrCreateInstance().Subscribe(topicName, callback);
        }
    }
}

using UnityEngine;

namespace Sim.Utils {
    public class RigidbodyAdapter : IPhysicsBody {
        private Rigidbody rb;

        public RigidbodyAdapter(Rigidbody rb) {
            this.rb = rb;
        }

        public Vector3 position { get => rb.position; set => rb.position = value; }
        public Vector3 centerOfMass { get => rb.centerOfMass; set => rb.centerOfMass = value; }
        public Quaternion rotation { get => rb.rotation; set => rb.rotation = value; }
        public Transform transform { get => rb.transform; }
        public Vector3 linearVelocity { get => rb.linearVelocity; set => rb.linearVelocity = value; }
        public Vector3 angularVelocity { get => rb.angularVelocity; set => rb.angularVelocity = value; }
        public Vector3 inertiaTensor { get => rb.inertiaTensor; set => rb.inertiaTensor = value; }
        public Quaternion inertiaTensorRotation { get => rb.inertiaTensorRotation; set => rb.inertiaTensorRotation = value; }
        public Vector3 GetAccumulatedTorque(float step)
            => rb.GetAccumulatedTorque(step);
        public Vector3 GetAccumulatedTorque()
            => rb.GetAccumulatedTorque();

        public float maxLinearVelocity { get => rb.maxLinearVelocity; set => rb.maxLinearVelocity = value; }
        public float maxAngularVelocity { get => rb.maxAngularVelocity; set => rb.maxAngularVelocity = value; }

        public void AddForce(Vector3 force, ForceMode mode = ForceMode.Force)
            => rb.AddForce(force, mode);

        public void AddRelativeForce(Vector3 force, ForceMode mode = ForceMode.Force)
            => rb.AddRelativeForce(force, mode);

        public void AddForceAtPosition(Vector3 force, Vector3 position, ForceMode mode = ForceMode.Force)
            => rb.AddForceAtPosition(force, position, mode);

        public void AddTorque(Vector3 torque, ForceMode mode = ForceMode.Force)
            => rb.AddTorque(torque, mode);

        public void AddRelativeTorque(Vector3 torque, ForceMode mode = ForceMode.Force)
            => rb.AddRelativeTorque(torque, mode);
    }
}

using System.Diagnostics;
using System.IO;
using System;
using UnityEngine;

namespace Sim.Utils {
    public class CommonUtils : MonoBehaviour {
        private string path = "Assets/Data/";

        // Called in Submerged.cs/GetSubmergedTriangles().
        // Retuns the normal vector of a triangle given its vertices.
        public static Vector3 GetFaceNormal(Vector3 A, Vector3 B, Vector3 C) {
            Vector3 normal = 0.5f * Vector3.Cross((B - A), (C - A));
            return normal;
        }

        public static Vector3 GetAveragePoint(Vector3[] vecs) {
            Vector3 tot = Vector3.zero;
            foreach (Vector3 v in vecs) {
                tot += v;
            }
            return tot / vecs.Length;
        }

        public static void DebugDrawTriangle(Vector3[] triangle, Color color) {
            UnityEngine.Debug.DrawLine(triangle[0], triangle[1], color);
            UnityEngine.Debug.DrawLine(triangle[0], triangle[2], color);
            UnityEngine.Debug.DrawLine(triangle[1], triangle[2], color);
        }

        // Using generics to logdata to a csv file. First parameter is file path,
        // second and third are the data to be logged.
        public static void LogDataToFile<T1, T2>(string filePath, T1 x, T2 y) {
            string data = $"{x},{y}";
            using (StreamWriter sw = File.AppendText(filePath)) {
                sw.WriteLine(data);
            }
        }

        // Measures the time of an action. Lambda expressions are used to pass the action.
        public static double MeasureExecutionTime(Action action) {
            Stopwatch stopwatch = new Stopwatch();
            stopwatch.Start();
            action();
            stopwatch.Stop();
            return stopwatch.Elapsed.TotalMilliseconds;
        }

        public (string depthLogFile, string timeLogFile) InitializeLogs(bool logVolumeData, bool logTimeData) {
            string depthLogFile = path + "VolumeData-" + transform.name + ".csv";
            string timeLogFile = path + "TimeData-" + transform.name + ".csv";

            if (!File.Exists(depthLogFile) && logVolumeData) {
                print("Beginning to log volume data");
                LogDataToFile(depthLogFile, "depth", "volume");
                // Add a constant downward force
                GetComponent<Rigidbody>().linearVelocity = new Vector3(0f, -0.1f, 0f);
            }

            if (!File.Exists(timeLogFile) && logTimeData) {
                print("Beginning to log time data");
                LogDataToFile(timeLogFile, "iteration_number", "time");
            }

            return (depthLogFile, timeLogFile);
        }
    }
}

